/* 英语「🗣 口语」的内容（speak.js 用）：情景对话 dialogs、常用表达 functions、发音 pron（最小对立词 pairs、连读 connected、跟读句 shadow）、话题卡 topics。
   由 Claude 生成后人工抽查；改内容直接改这个文件里的 JSON。 */
window.SPEAK_DATA = {"dialogs": [{"id": "mamak_order","title": "在 mamak 点餐","en_title": "Ordering at a Mamak","level": "入门","scene": "你在家附近的 mamak 档坐下，伙计过来点单，你要点拉茶、印度煎饼，还要打包一份。","roles": {"A": "mamak 伙计","B": "顾客"},"lines": [{"who": "A","en": "Hi, boss! What would you like?","zh": "老板你好！要点什么？"},{"who": "B","en": "Um, can I get one teh tarik, kurang manis?","zh": "嗯，给我一杯拉茶，少糖，可以吗？"},{"who": "A","en": "Teh tarik kurang manis. Hot or iced?","zh": "拉茶少糖。要热的还是冰的？"},{"who": "B","en": "Iced, please. And less ice, if possible.","zh": "冰的，谢谢。可以的话少冰。"},{"who": "A","en": "Okay. Anything to eat?","zh": "好。要吃点什么吗？"},{"who": "B","en": "Yeah, I'll have two roti canai. Can I get extra dhal on the side?","zh": "要，来两份印度煎饼。咖喱豆酱能多给一点、另外放吗？"},{"who": "A","en": "Sure. Dine in or tapau?","zh": "可以。在这吃还是打包？"},{"who": "B","en": "Actually, can you tapau one of them? I'll eat the other one here.","zh": "其实可以帮我打包一份吗？另一份我在这吃。"},{"who": "A","en": "No problem. One here, one takeaway. Anything else?","zh": "没问题。一份堂食，一份外带。还要别的吗？"},{"who": "B","en": "Oh, and one Milo ais to go, too.","zh": "哦，再来一杯冰美禄，外带。"},{"who": "A","en": "Okay, Milo ais tapau. Is that everything?","zh": "好，冰美禄打包。就这些了吗？"},{"who": "B","en": "Yep, that's it. How much is it altogether?","zh": "对，就这些。一共多少钱？"},{"who": "A","en": "Altogether it's RM12.50.","zh": "一共 12 令吉 50 仙。"},{"who": "B","en": "Can I pay with Touch 'n Go?","zh": "可以用 Touch 'n Go 付吗？"},{"who": "A","en": "Sure, just scan the QR code over there.","zh": "可以，扫那边的二维码就行。"},{"who": "B","en": "Great, thanks! I'm at table five, by the way.","zh": "好的，谢谢！对了，我坐五号桌。"}],"phrases": [["Can I get...?","点餐最自然的说法，比 I want 礼貌，例：Can I get one teh tarik?"],["kurang manis","马来语“少糖”，在马来西亚点饮料通用；英文可说 less sweet"],["less ice, if possible","可以的话少冰；if possible 让请求更客气"],["on the side","（酱料等）另外放、放旁边"],["Dine in or tapau?","在这吃还是打包？tapau 是本地通用的“打包”"],["to go","外带，等于 takeaway"],["That's it.","就这些了（点完单时说）"],["How much is it altogether?","一共多少钱？"]],"tip": "mamak 伙计叫你 boss 很正常；点单用 Can I get...，打包直接说 tapau 或 to go，本地人都听得懂。"},{"id": "grab_ride","title": "坐 Grab","en_title": "Taking a Grab Ride","level": "基础","scene": "你叫了一辆 Grab 去 Mid Valley，上车后和司机确认目的地、商量走哪条路，最后下车。","roles": {"A": "Grab 司机","B": "乘客"},"lines": [{"who": "A","en": "Hi, Alex? Going to Mid Valley, right?","zh": "你好，是 Alex 吗？去 Mid Valley 对吧？"},{"who": "B","en": "Yes, that's me. The North Court entrance, please.","zh": "对，是我。麻烦到北庭入口。"},{"who": "A","en": "Okay. There's a jam on Federal Highway, so I'll go through Bangsar, okay?","zh": "好。联邦大道在塞车，我走 Bangsar 那边，可以吗？"},{"who": "B","en": "Sure, whatever's faster. How long do you think it'll take?","zh": "可以，哪条快走哪条。你觉得要多久？"},{"who": "A","en": "About twenty minutes, depending on traffic.","zh": "大概二十分钟，看路况。"},{"who": "B","en": "That's fine. Um, could you turn the AC down a little? It's kinda cold.","zh": "没问题。嗯，空调能调小一点吗？有点冷。"},{"who": "A","en": "No problem. Is this better?","zh": "没问题。这样好点吗？"},{"who": "B","en": "Perfect, thanks. So, do you drive full-time?","zh": "刚好，谢谢。那你是全职开车吗？"},{"who": "A","en": "Yeah, about three years already. Are you from China?","zh": "是啊，大概三年了。你是中国来的吗？"},{"who": "B","en": "Yeah, but I've been living in KL for a while now.","zh": "对，不过我在吉隆坡住了挺久了。"},{"who": "A","en": "Okay, we're almost there. North Court is on the left.","zh": "好，快到了。北庭在左边。"},{"who": "B","en": "You can just drop me off here, by the entrance.","zh": "在这儿入口旁边放我下来就行。"},{"who": "A","en": "Sure. You paid by card in the app, right?","zh": "好的。你是在 app 里用卡付的，对吧？"},{"who": "B","en": "Yep, it's already paid. Thanks so much, have a good one!","zh": "对，已经付了。非常感谢，祝你愉快！"}],"phrases": [["That's me.","就是我（司机确认乘客身份时回答）"],["whatever's faster","哪个快就哪个，表示让对方决定"],["How long do you think it'll take?","你觉得要多久？问时间很常用"],["depending on traffic","看路况而定；depending on 表示“取决于”"],["turn the AC down","把空调调小；调大是 turn it up"],["I've been living in KL for a while now.","我在吉隆坡住了一段时间了，用现在完成进行时"],["drop me off here","在这儿放我下车"],["Have a good one!","祝你愉快，美式万能道别语"]],"tip": "下车说 drop me off here，不要说 put me down；上车先报具体入口或地标，能少绕很多路。"},{"id": "coffee_shop","title": "咖啡店点单","en_title": "Ordering at a Coffee Shop","level": "入门","scene": "你在公司楼下的咖啡店买一杯冰拿铁，要选杯型、换燕麦奶、少冰，带走，还要报名字。","roles": {"A": "咖啡师","B": "顾客"},"lines": [{"who": "A","en": "Hi there! What can I get for you?","zh": "你好！要点什么？"},{"who": "B","en": "Hi! Can I get an iced latte, please?","zh": "你好！我要一杯冰拿铁，谢谢。"},{"who": "A","en": "Sure. What size? We've got regular and large.","zh": "好。要什么杯型？我们有中杯和大杯。"},{"who": "B","en": "Regular is fine. Could I get that with oat milk?","zh": "中杯就行。可以换成燕麦奶吗？"},{"who": "A","en": "Of course. Oat milk is two ringgit extra. Is that okay?","zh": "当然。燕麦奶要加两令吉，可以吗？"},{"who": "B","en": "Yeah, that's fine. Oh, and less ice, please.","zh": "可以。哦，还有少冰，谢谢。"},{"who": "A","en": "Got it. Any sugar or syrup?","zh": "好的。要加糖或糖浆吗？"},{"who": "B","en": "Um, just half sweet. Do you have vanilla?","zh": "嗯，半糖就好。你们有香草的吗？"},{"who": "A","en": "We do. Half sweet vanilla, then. For here or to go?","zh": "有。那就半糖香草。在这喝还是带走？"},{"who": "B","en": "To go, please.","zh": "带走，谢谢。"},{"who": "A","en": "Can I get a name for the order?","zh": "这单留个名字好吗？"},{"who": "B","en": "Sure, it's Alex. A-L-E-X.","zh": "好，叫 Alex，A-L-E-X。"},{"who": "A","en": "Thanks, Alex. That'll be fifteen ringgit.","zh": "谢谢 Alex，一共十五令吉。"},{"who": "B","en": "Can I pay by card?","zh": "可以刷卡吗？"},{"who": "A","en": "Yep, just tap here. It'll be ready at the end of the counter.","zh": "可以，在这儿拍一下。做好了在柜台尽头取。"},{"who": "B","en": "Awesome, thank you!","zh": "太好了，谢谢！"}],"phrases": [["What can I get for you?","店员常用开场：要点什么？"],["Can I get an iced latte, please?","点单万能句型 Can I get... please?"],["Regular is fine.","中杯就行；... is fine 表示“……就可以”"],["Could I get that with oat milk?","可以换成燕麦奶吗？with 后接你想加或换的东西"],["less ice","少冰；去冰是 no ice"],["For here or to go?","在这喝还是带走？"],["Can I get a name for the order?","店员问名字，回答 Sure, it's...，可以顺便拼出来"],["Can I pay by card?","可以刷卡吗？"]],"tip": "点单别说 I want...，用 Can I get... 或 I'll have... 更自然；名字容易被写错，直接拼一遍字母。"},{"id": "small_talk_neighbor","title": "电梯里和邻居闲聊","en_title": "Small Talk with a Neighbor","level": "基础","scene": "早上在 condo 电梯里遇到一位没见过的邻居，你们聊天气、你搬来多久、周末打算。","roles": {"A": "邻居 Mei","B": "你"},"lines": [{"who": "A","en": "Morning! Hot one today, huh?","zh": "早！今天好热啊？"},{"who": "B","en": "Morning! Yeah, it's crazy hot. I was sweating just walking to the car park.","zh": "早！是啊热疯了。我走到停车场就出汗了。"},{"who": "A","en": "Ha, tell me about it. Are you new here? I don't think I've seen you before.","zh": "哈，可不是嘛。你是新搬来的吗？好像没见过你。"},{"who": "B","en": "Yeah, I just moved in last month. I'm on the eighteenth floor.","zh": "对，我上个月刚搬进来，住在十八楼。"},{"who": "A","en": "Oh, nice! Welcome to the building. How are you finding it so far?","zh": "哦，不错！欢迎入住。到目前为止觉得怎么样？"},{"who": "B","en": "So far so good. It's quiet, and the LRT is pretty close, which is great.","zh": "目前挺好的。很安静，离轻轨也挺近，这点很棒。"},{"who": "A","en": "Yeah, that's the best part. Where'd you move from?","zh": "对，这是最好的一点。你从哪搬过来的？"},{"who": "B","en": "I was in Cheras before, but it was kind of far from my office.","zh": "我之前住 Cheras，不过离公司有点远。"},{"who": "A","en": "Makes sense. Got any plans for the weekend?","zh": "有道理。周末有什么安排吗？"},{"who": "B","en": "Not really. I might check out the night market nearby. Is it any good?","zh": "没什么安排。可能去附近的夜市逛逛。那里好吗？"},{"who": "A","en": "Oh, it's great. You have to try the satay there.","zh": "哦，很不错。你一定要试试那里的沙爹。"},{"who": "B","en": "Good to know, thanks! I'm Alex, by the way.","zh": "知道了，谢谢！对了，我叫 Alex。"},{"who": "A","en": "I'm Mei. Nice to meet you, Alex.","zh": "我是 Mei。很高兴认识你，Alex。"},{"who": "B","en": "Nice to meet you too. Oh, this is my floor. See you around!","zh": "我也很高兴认识你。哦，我到了。回头见！"}],"phrases": [["Hot one today, huh?","今天好热啊？聊天气的经典开场"],["Tell me about it.","可不是嘛（表示强烈同意，不是真的让你讲）"],["I just moved in last month.","我上个月刚搬进来"],["How are you finding it so far?","到目前为止觉得怎么样？find 在这里是“觉得”"],["So far so good.","目前为止还不错"],["Got any plans for the weekend?","周末有安排吗？口语省略了 Have you"],["..., by the way.","顺便说一下，放句尾用来自然地自我介绍或转话题"],["See you around!","回头见，适合不确定下次何时见的邻居、同事"]],"tip": "Tell me about it 是“可不是嘛”，别当成“跟我讲讲”；电梯闲聊不用太深，最后用 See you around 自然收尾。"},{"id": "clinic_visit","title": "诊所看病","en_title": "Seeing a Doctor at a Clinic","level": "进阶","scene": "你喉咙痛、发烧好几天了，去家附近的诊所，向医生描述症状、说明过敏、问清楚药怎么吃，再要一张病假单。","roles": {"A": "医生","B": "病人"},"lines": [{"who": "A","en": "Hi, have a seat. So, what brings you in today?","zh": "你好，请坐。今天哪里不舒服？"},{"who": "B","en": "Hi, doctor. I've had a sore throat and a bit of a fever.","zh": "医生你好。我喉咙痛，还有点发烧。"},{"who": "A","en": "I see. How long have you been feeling like this?","zh": "我知道了。这样多久了？"},{"who": "B","en": "It started about three days ago. It's gotten worse since yesterday.","zh": "大概三天前开始的，从昨天起更严重了。"},{"who": "A","en": "Any coughing or a runny nose?","zh": "有咳嗽或流鼻涕吗？"},{"who": "B","en": "I've got a dry cough, especially at night. No runny nose, though.","zh": "有干咳，尤其是晚上。不过没流鼻涕。"},{"who": "A","en": "Okay. Are you allergic to any medication?","zh": "好。你对什么药物过敏吗？"},{"who": "B","en": "Actually, yes. I'm allergic to penicillin.","zh": "其实有，我对青霉素过敏。"},{"who": "A","en": "Good thing you told me. Let me take a look. Open your mouth, please.","zh": "幸好你说了。我看一下，请张开嘴。"},{"who": "B","en": "Is it serious? Do I need antibiotics?","zh": "严重吗？需要吃抗生素吗？"},{"who": "A","en": "It looks viral, so no antibiotics. I'll give you something for the fever and the cough.","zh": "看起来是病毒感染，所以不用抗生素。我给你开退烧和止咳的药。"},{"who": "B","en": "Okay. How should I take them?","zh": "好的。这些药要怎么吃？"},{"who": "A","en": "One fever tablet every six hours if needed. The syrup, ten ml three times a day after meals.","zh": "退烧药需要时每六小时吃一粒。药水每天三次，饭后每次十毫升。"},{"who": "B","en": "Got it. Will it make me drowsy?","zh": "明白了。吃了会犯困吗？"},{"who": "A","en": "The syrup might, so try not to drive. And drink plenty of water and get some rest.","zh": "药水可能会，所以尽量别开车。还有多喝水、多休息。"},{"who": "B","en": "Thanks, doctor. Could I also get an MC for work?","zh": "谢谢医生。能再给我开一张病假单吗？"}],"phrases": [["What brings you in today?","医生开场：今天怎么了？"],["I've had a sore throat.","我喉咙痛（持续了一段时间，用现在完成时）"],["It started about three days ago.","大概三天前开始的，说明症状多久了"],["It's gotten worse since yesterday.","从昨天起更严重了"],["I'm allergic to penicillin.","我对青霉素过敏；be allergic to + 东西"],["How should I take them?","药要怎么吃？"],["Will it make me drowsy?","会让我犯困吗？drowsy = 困倦"],["Could I get an MC?","能开病假单吗？MC = medical certificate，马来西亚请病假要用"]],"tip": "说症状持续多久用 I've had ... for three days 或 It started three days ago，别说 I have ... since three days；有过敏一定主动说。"},{"id": "landlord_repair","title": "打电话给房东报修","en_title": "Calling the Landlord for a Repair","level": "基础","scene": "你租的 condo 主卧空调在漏水，你打电话给房东说明情况，约师傅上门的时间，顺便问修理费谁出。","roles": {"A": "房东 Mr. Tan","B": "租客"},"lines": [{"who": "A","en": "Hello?","zh": "喂？"},{"who": "B","en": "Hi, Mr. Tan. It's Alex from unit 18-3. Sorry to bother you.","zh": "你好陈先生，我是 18-3 的 Alex。不好意思打扰你。"},{"who": "A","en": "Oh, hi Alex. No problem. What's up?","zh": "哦，你好 Alex。没事，怎么了？"},{"who": "B","en": "The air-con in the master bedroom is leaking. Water's dripping onto the floor.","zh": "主卧的空调在漏水，水滴到地板上了。"},{"who": "A","en": "Oh no. Since when?","zh": "哎呀。什么时候开始的？"},{"who": "B","en": "I noticed it last night. I put a bucket under it, but it's getting worse.","zh": "我昨晚发现的。我在下面放了个桶，但越来越严重了。"},{"who": "A","en": "It's probably the drainage pipe. I'll get my technician to check it.","zh": "可能是排水管的问题。我叫师傅去看看。"},{"who": "B","en": "That'd be great. When do you think he can come?","zh": "那太好了。你觉得他什么时候能来？"},{"who": "A","en": "How about Saturday morning, around ten?","zh": "星期六早上十点左右怎么样？"},{"who": "B","en": "Hmm, I'm out on Saturday morning. Would the afternoon work instead?","zh": "嗯，我星期六早上不在。改成下午可以吗？"},{"who": "A","en": "Let me check with him... Okay, two o'clock is fine.","zh": "我问问他……好，两点可以。"},{"who": "B","en": "Two works for me. In the meantime, should I stop using that air-con?","zh": "两点我可以。在那之前，我是不是先别用那台空调？"},{"who": "A","en": "Yeah, better not use it for now.","zh": "对，暂时最好别用。"},{"who": "B","en": "Got it. Also, just to check, is the repair on you, or do I pay for it?","zh": "明白。另外确认一下，修理费是你出还是我出？"},{"who": "A","en": "Don't worry, I'll cover it. It's just normal wear and tear.","zh": "别担心，我来付。这只是正常损耗。"},{"who": "B","en": "Thanks so much, Mr. Tan. See you on Saturday, then.","zh": "太感谢了陈先生。那星期六见。"}],"phrases": [["It's Alex from unit 18-3.","打电话自报身份：我是某单位的某某"],["Sorry to bother you.","不好意思打扰你，打电话开场很礼貌"],["The air-con is leaking.","空调在漏水；leak = 漏"],["When do you think he can come?","你觉得他什么时候能来？"],["Would the afternoon work instead?","改成下午可以吗？提出替代时间的礼貌说法"],["Two works for me.","两点我可以；... works for me 表示时间合适"],["Is the repair on you?","修理费你出吗？be on you = 由你买单"],["wear and tear","正常损耗（租房、保险里常见）"]],"tip": "打电话先报单位号和名字；约时间不合适就说 Would ... work instead?；修之前先问清楚 is it on you，免得之后扯皮。"},{"id": "bank_account","title": "银行开户、问转账手续费","en_title": "Opening a Bank Account","level": "进阶","scene": "你拿着工作准证去银行柜台开储蓄账户，问清需要的材料、最低存款、月费，以及汇钱回国的手续费和到账时间。","roles": {"A": "银行职员","B": "客户"},"lines": [{"who": "A","en": "Good morning. How can I help you today?","zh": "早上好。今天要办什么业务？"},{"who": "B","en": "Hi, I'd like to open a savings account, please.","zh": "你好，我想开一个储蓄账户。"},{"who": "A","en": "Sure. Are you a Malaysian citizen?","zh": "好的。你是马来西亚公民吗？"},{"who": "B","en": "No, I'm a foreigner. I'm here on an employment pass.","zh": "不是，我是外国人，持工作准证在这里。"},{"who": "A","en": "Okay. Then I'll need your passport, your employment pass, and a letter from your employer.","zh": "好。那我需要你的护照、工作准证和公司开的证明信。"},{"who": "B","en": "I've got all of those here. Do I also need proof of address?","zh": "这些我都带了。还需要地址证明吗？"},{"who": "A","en": "Yes, a utility bill or your tenancy agreement would be fine.","zh": "需要，水电账单或租约都可以。"},{"who": "B","en": "Great, here's my tenancy agreement. Is there a minimum deposit?","zh": "好，这是我的租约。有最低存款要求吗？"},{"who": "A","en": "Yes, the minimum initial deposit is RM250.","zh": "有，首次最低存款是 250 令吉。"},{"who": "B","en": "Okay. And are there any monthly fees?","zh": "好。那有月费吗？"},{"who": "A","en": "No monthly fee, as long as your balance stays above RM1,000.","zh": "只要余额保持在 1000 令吉以上，就没有月费。"},{"who": "B","en": "Got it. Um, I'll be sending money home too. What are the fees for overseas transfers?","zh": "明白。嗯，我还会往国内汇钱。境外转账手续费是多少？"},{"who": "A","en": "It's RM10 per transfer, plus the exchange rate on the day. You can do it in our app, too.","zh": "每笔 10 令吉，再按当天汇率计算。也可以在我们的 app 上操作。"},{"who": "B","en": "And how long does it usually take to arrive?","zh": "那一般多久能到账？"},{"who": "A","en": "Normally one to three working days.","zh": "通常一到三个工作日。"},{"who": "B","en": "That's really helpful, thanks. Let's go ahead and open the account.","zh": "很有帮助，谢谢。那我们开始开户吧。"}],"phrases": [["I'd like to open a savings account.","我想开一个储蓄账户；I'd like to 比 I want to 礼貌"],["I'm here on an employment pass.","我持工作准证在这里；be here on + 签证类型"],["proof of address","地址证明（水电账单、租约等）"],["Is there a minimum deposit?","有最低存款要求吗？"],["Are there any monthly fees?","有月费吗？问隐藏费用必备"],["What are the fees for overseas transfers?","境外转账手续费是多少？"],["How long does it usually take to arrive?","一般多久到账？"],["Let's go ahead and...","那我们就开始……，表示决定办理"]],"tip": "办业务开头用 I'd like to...；钱相关的一定追问 Are there any fees? 和 How long does it take?，问清再办。"},{"id": "shopping_return","title": "商场退换货","en_title": "Returning Clothes at the Mall","level": "基础","scene": "你上周在商场买的衬衫太紧，想换大一号，但是小票找不到了，你去柜台问店员怎么办。","roles": {"A": "店员","B": "顾客"},"lines": [{"who": "A","en": "Hi, can I help you with anything?","zh": "你好，有什么可以帮你的吗？"},{"who": "B","en": "Hi, yes. I bought this shirt here last week, but it doesn't fit.","zh": "你好。我上周在这买了这件衬衫，但是不合身。"},{"who": "A","en": "Oh, sorry about that. Is it too big or too small?","zh": "哦，抱歉。是太大还是太小？"},{"who": "B","en": "It's a bit tight around the shoulders. Can I exchange it for a size up?","zh": "肩膀那里有点紧。可以换大一号吗？"},{"who": "A","en": "Sure. Do you have the receipt with you?","zh": "可以。你带小票了吗？"},{"who": "B","en": "Um, actually, I think I lost it. Is that a problem?","zh": "嗯，其实我好像弄丢了。这样有问题吗？"},{"who": "A","en": "Hmm. Did you pay by card?","zh": "嗯。你是刷卡付的吗？"},{"who": "B","en": "Yes, my debit card. I can show you the transaction in my banking app.","zh": "对，用的借记卡。我可以给你看银行 app 里的交易记录。"},{"who": "A","en": "That works. And the tags are still on?","zh": "那可以。吊牌都还在吗？"},{"who": "B","en": "Yep, I haven't worn it. The tags are all still on.","zh": "在，我没穿过，吊牌都还在。"},{"who": "A","en": "Great. Let me see if we have it in large... Yes, here you go.","zh": "好。我看看有没有大号的……有，给你。"},{"who": "B","en": "Thanks. Can I try it on first, just to make sure?","zh": "谢谢。我能先试一下吗，确认一下。"},{"who": "A","en": "Of course. The fitting room is right over there.","zh": "当然。试衣间就在那边。"},{"who": "B","en": "Okay, this one fits perfectly. I'll take it.","zh": "好，这件刚好合身，就要这件。"},{"who": "A","en": "Great. It's the same price, so it's a straight exchange. No extra charge.","zh": "好的。价格一样，直接换就行，不用补钱。"},{"who": "B","en": "Perfect. Thanks so much for your help!","zh": "太好了。非常感谢你的帮忙！"}],"phrases": [["It doesn't fit.","不合身；别说 it's not fit"],["It's a bit tight around the shoulders.","肩膀那里有点紧；tight 紧，loose 松"],["Can I exchange it for a size up?","可以换大一号吗？小一号是 a size down"],["Do you have the receipt with you?","你带小票了吗？"],["I think I lost it. Is that a problem?","我好像弄丢了，有问题吗？委婉说明情况"],["The tags are still on.","吊牌还在，退换货的关键条件"],["Can I try it on?","我能试穿吗？try on 试穿"],["I'll take it.","就要这个了，决定购买时说"]],"tip": "没小票先别慌，主动提出给店员看刷卡记录；换货是 exchange，退款是 refund，说清楚你要哪一种。"},{"id": "self_intro_meetup","title": "技术 meetup 认识新朋友","en_title": "Meeting Someone at a Tech Meetup","level": "入门","scene": "你在吉隆坡一场技术 meetup 上，旁边坐下一个陌生人，你要自我介绍、聊聊工作，最后交换联系方式。","roles": {"A": "Jake（产品经理）","B": "你（程序员）"},"lines": [{"who": "A","en": "Hey, is this seat taken?","zh": "嘿，这个位子有人吗？"},{"who": "B","en": "No, go ahead. I'm Wei, by the way.","zh": "没人，坐吧。对了，我叫 Wei。"},{"who": "A","en": "Nice to meet you, Wei. I'm Jake. Is this your first time here?","zh": "很高兴认识你，Wei。我是 Jake。你是第一次来吗？"},{"who": "B","en": "Yeah, it's my first time. A friend told me about it.","zh": "对，第一次来。是一个朋友跟我说的。"},{"who": "A","en": "Cool. So what do you do?","zh": "不错。那你是做什么的？"},{"who": "B","en": "I'm a software developer. I mostly work on the backend.","zh": "我是软件开发，主要做后端。"},{"who": "A","en": "Oh nice. What kind of stack are you using?","zh": "哦，挺好。你们用什么技术栈？"},{"who": "B","en": "Mostly Python and Go. We're moving some stuff to the cloud right now.","zh": "主要是 Python 和 Go。我们现在正在把一些东西迁到云上。"},{"who": "A","en": "That sounds fun. I'm a product manager at a fintech startup near KLCC.","zh": "听起来挺有意思。我在 KLCC 附近一家金融科技创业公司做产品经理。"},{"who": "B","en": "Oh really? What does your company do, if you don't mind me asking?","zh": "真的吗？方便问一下你们公司是做什么的吗？"},{"who": "A","en": "We build payment tools for small shops. Kind of like Touch 'n Go, but for businesses.","zh": "我们给小店做支付工具。有点像 Touch 'n Go，不过是给商家用的。"},{"who": "B","en": "That's really interesting. I'd love to hear more about it sometime.","zh": "真有意思。改天很想多听你讲讲。"},{"who": "A","en": "Sure! Are you on LinkedIn?","zh": "当然！你用 LinkedIn 吗？"},{"who": "B","en": "Yeah, I am. Let me scan your QR code.","zh": "用的。我扫一下你的二维码。"},{"who": "A","en": "Here you go. We should grab coffee sometime.","zh": "给你。改天一起喝杯咖啡吧。"},{"who": "B","en": "Sounds great. It was really nice talking to you.","zh": "好啊。跟你聊天很开心。"}],"phrases": [["Is this seat taken?","这个位子有人吗？在会场、咖啡店找座位时最常用"],["..., by the way","顺便说一下；放在句尾自然地带出自己的名字或补充信息"],["So what do you do?","你是做什么工作的？比 What's your job? 自然、礼貌得多"],["I mostly work on ...","我主要负责……，介绍工作内容的万能句"],["if you don't mind me asking","如果你不介意我问的话；问稍私人的问题前加上更客气"],["I'd love to hear more about it sometime","改天很想多听听；表达兴趣、为后续联系铺垫"],["grab coffee sometime","改天喝个咖啡；口语里约人见面的轻松说法"],["It was really nice talking to you","跟你聊得很开心；准备结束对话时用"]],"tip": "问职业用 What do you do?，别说 What's your job?（听着像查户口）；要走时说 It was nice talking to you，用过去式 was 表示这次聊天要结束了。"},{"id": "standup_meeting","title": "线上站会汇报进度","en_title": "Daily Stand-up Meeting","level": "基础","scene": "你是开发，正在开每天早上的线上站会，轮到你说昨天做了什么、今天要做什么，还有一个卡住你的问题。","roles": {"A": "组长（主持人）","B": "你（开发）"},"lines": [{"who": "A","en": "Morning, everyone. Let's get started. Wei, do you want to go first?","zh": "大家早。我们开始吧。Wei，你先来？"},{"who": "B","en": "Sure. Yesterday I finished the login API and pushed it for review.","zh": "好。昨天我做完了登录接口，已经提交去 review 了。"},{"who": "A","en": "Nice. Has anyone picked up the review yet?","zh": "不错。有人接了这个 review 吗？"},{"who": "B","en": "Not yet. Could someone take a look at it today?","zh": "还没有。今天能有人帮忙看一下吗？"},{"who": "A","en": "I'll ask Sarah to review it. What are you working on today?","zh": "我让 Sarah 来看。你今天做什么？"},{"who": "B","en": "Today I'm going to start on the password reset feature.","zh": "今天我要开始做重置密码的功能。"},{"who": "A","en": "Sounds good. Any blockers?","zh": "好的。有什么卡住的吗？"},{"who": "B","en": "Actually, yeah. I'm blocked on the email service.","zh": "其实有。我卡在邮件服务那里了。"},{"who": "A","en": "Oh, what's going on with it?","zh": "哦，它怎么了？"},{"who": "B","en": "I don't have access to the staging account, so I can't test it.","zh": "我没有 staging 账号的权限，所以没法测。"},{"who": "A","en": "Got it. I'll ping DevOps right after this call.","zh": "明白。开完会我马上找 DevOps。"},{"who": "B","en": "Thanks. In the meantime, I'll work on the unit tests.","zh": "谢谢。这期间我先写单元测试。"},{"who": "A","en": "Perfect. Anything else?","zh": "很好。还有别的吗？"},{"who": "B","en": "Nope, that's it from me.","zh": "没了，我这边就这些。"},{"who": "A","en": "Great. Okay, Sarah, you're up.","zh": "好。那 Sarah，轮到你了。"}],"phrases": [["Do you want to go first?","你要先来吗？会议里点名或谦让顺序时用"],["pushed it for review","已经提交去代码评审；push 在这里就是提交代码"],["Could someone take a look at it?","能有人帮忙看一下吗？请人 review 或帮忙的客气说法"],["Any blockers?","有没有卡住你的问题？站会必问的一句"],["I'm blocked on ...","我卡在……上了；blocked on 后面接卡住你的东西"],["I'll ping ... right after this call","开完会我马上联系……；ping 是工作口语里的发消息、找人"],["In the meantime","在这期间；等别人处理时说自己先做什么"],["That's it from me","我这边就这些；汇报结束时的标准收尾"]],"tip": "站会三段式：Yesterday I... / Today I'm going to... / I'm blocked on...；说完用 That's it from me 收尾，别说 I'm finished 或 Over。"},{"id": "job_interview","title": "英文面试：介绍自己和项目","en_title": "Job Interview","level": "进阶","scene": "你在面试一家公司的后端开发岗位，面试官让你介绍自己、讲一个做过的项目，最后你也要向对方提问。","roles": {"A": "面试官","B": "你（求职者）"},"lines": [{"who": "A","en": "Thanks for coming in today. Could you start by telling me a bit about yourself?","zh": "谢谢你今天过来。可以先简单介绍一下你自己吗？"},{"who": "B","en": "Sure. I'm a backend developer with about five years of experience.","zh": "好的。我是后端开发，大概有五年经验。"},{"who": "A","en": "Great. And what are you working on right now?","zh": "好的。那你现在在做什么？"},{"who": "B","en": "Right now I'm at a logistics company, building APIs for our delivery app.","zh": "我现在在一家物流公司，给我们的配送 App 做接口。"},{"who": "A","en": "Can you walk me through a project you're proud of?","zh": "能给我详细讲讲一个你比较自豪的项目吗？"},{"who": "B","en": "Yeah. Last year, I led a project to speed up our order system.","zh": "可以。去年我带了一个项目，给我们的订单系统提速。"},{"who": "A","en": "What was the main challenge?","zh": "主要的难点是什么？"},{"who": "B","en": "The database got really slow during peak hours, like on big sale days.","zh": "高峰期数据库会变得特别慢，比如大促那几天。"},{"who": "A","en": "So how did you deal with that?","zh": "那你们是怎么解决的？"},{"who": "B","en": "We added caching and split up some heavy queries. Response time dropped by about sixty percent.","zh": "我们加了缓存，还拆了一些很重的查询。响应时间降了大约百分之六十。"},{"who": "A","en": "That's impressive. What did you learn from it?","zh": "很厉害。你从中学到了什么？"},{"who": "B","en": "I learned to measure first, before trying to fix anything.","zh": "我学到了要先测量，再动手去优化。"},{"who": "A","en": "Good answer. Do you have any questions for us?","zh": "回答得好。你有什么问题想问我们吗？"},{"who": "B","en": "Yes, actually. What does a typical day look like in this role?","zh": "有的。这个岗位平时一天大概是什么样的？"},{"who": "A","en": "Mostly coding, plus a couple of meetings with the product team.","zh": "大部分时间写代码，再加几个和产品团队的会。"},{"who": "B","en": "Got it. And what are the next steps in the process?","zh": "明白了。那接下来的面试流程是怎样的？"}],"phrases": [["Could you start by telling me a bit about yourself?","请先简单介绍一下自己；面试开场几乎必问"],["with about five years of experience","有大约五年经验；介绍资历的固定搭配"],["walk me through ...","一步步给我讲讲……；面试和工作中都很常用"],["a project you're proud of","你引以为豪的项目；自己说时改成 a project I'm proud of"],["How did you deal with that?","你是怎么处理的？deal with 就是应对、解决"],["dropped by about sixty percent","降低了约百分之六十；by 后面接变化的幅度"],["What does a typical day look like?","平时一天是什么样的？反问面试官的好问题"],["What are the next steps in the process?","接下来流程是什么？面试结尾问这个很自然"]],"tip": "讲项目用 STAR 顺序：背景、难点、你做了什么、结果，结果尽量带数字；最后一定准备一两个问题，直接说 No questions 会显得没兴趣。"},{"id": "disagree_politely","title": "委婉提出不同意见","en_title": "Disagreeing Politely","level": "进阶","scene": "同事提议把整个支付模块推倒重写，你觉得风险太大，要委婉表达不同意见、提出替代方案，最后两人达成一致。","roles": {"A": "同事","B": "你"},"lines": [{"who": "A","en": "So I think we should just rewrite the whole payment module from scratch.","zh": "我觉得我们干脆把整个支付模块从头重写。"},{"who": "B","en": "Hmm, I see where you're coming from. The code is pretty messy.","zh": "嗯，我理解你为什么这么想。代码确实挺乱的。"},{"who": "A","en": "Right? It's so hard to add anything new.","zh": "对吧？加点新东西都特别难。"},{"who": "B","en": "But I'm not sure a full rewrite is the best idea right now.","zh": "但我不太确定现在全部重写是不是最好的办法。"},{"who": "A","en": "Why not?","zh": "为什么？"},{"who": "B","en": "Well, we've got a big release next month. A rewrite could be pretty risky.","zh": "嗯，我们下个月有个大版本要发。重写风险可能挺大的。"},{"who": "A","en": "Okay, fair point. But we can't keep patching it forever.","zh": "好吧，有道理。但我们也不能一直打补丁啊。"},{"who": "B","en": "Totally agree. What if we refactor it step by step instead?","zh": "完全同意。那我们改成一步一步重构怎么样？"},{"who": "A","en": "Like, one part at a time?","zh": "你是说一次改一部分？"},{"who": "B","en": "Exactly. We could start with the refund logic, since it breaks the most.","zh": "对。可以先从退款逻辑开始，因为它最常出问题。"},{"who": "A","en": "Hmm, that could work. But how do we make sure it doesn't drag on?","zh": "嗯，这样可行。但怎么保证它不会一直拖下去？"},{"who": "B","en": "How about we set aside one day every sprint for it?","zh": "要不每个迭代专门留一天来做这个？"},{"who": "A","en": "Okay, I can live with that. Let's try it for two sprints.","zh": "行，我可以接受。先试两个迭代吧。"},{"who": "B","en": "Sounds good. Let's run it by the team on Monday.","zh": "好。周一我们跟团队提一下，听听大家意见。"}],"phrases": [["I see where you're coming from","我理解你的出发点；反对之前先表示理解"],["I'm not sure ... is the best idea","我不太确定……是不是最好的主意；委婉表达不同意"],["Fair point","有道理；承认对方说得对，但不一定完全同意"],["What if we ... instead?","要不我们改成……怎么样？把反对变成提议"],["How about we ...?","我们……怎么样？提出具体方案，后面直接接动词原形句"],["drag on","拖拖拉拉、没完没了；常说 It's dragging on"],["I can live with that","我可以接受；不算完美但同意了"],["run it by the team","跟团队过一下、征求意见"]],"tip": "先认同再转折：I see your point, but... / I'm not sure...；别直接说 You're wrong 或 I don't agree，用 What if we... 把反对变成一个提议。"},{"id": "phone_booking","title": "打电话订餐厅","en_title": "Booking a Table by Phone","level": "入门","scene": "你打电话给一家餐厅，订周六晚上的位子：说清人数、时间、想要的座位，再报名字和电话。","roles": {"A": "餐厅店员","B": "你（顾客）"},"lines": [{"who": "A","en": "Hi, thanks for calling Bunga Kitchen. How can I help you?","zh": "您好，这里是 Bunga Kitchen。有什么可以帮您？"},{"who": "B","en": "Hi, I'd like to make a reservation for this Saturday, please.","zh": "你好，我想订这周六的位子。"},{"who": "A","en": "Sure. How many people will it be?","zh": "好的。一共几位？"},{"who": "B","en": "There'll be six of us, including two kids.","zh": "我们六个人，包括两个小孩。"},{"who": "A","en": "And what time would you like?","zh": "您想订几点？"},{"who": "B","en": "Around seven thirty, if possible.","zh": "如果可以的话，七点半左右。"},{"who": "A","en": "Let me check... Seven thirty is full, but we have a table at eight.","zh": "我查一下……七点半满了，八点有位子。"},{"who": "B","en": "Eight works. Could we get a table by the window?","zh": "八点可以。能给我们靠窗的位子吗？"},{"who": "A","en": "I'll make a note, but I can't promise. Can I have your name, please?","zh": "我会备注一下，但不能保证。请问您贵姓？"},{"who": "B","en": "Sure, it's Wei. That's W-E-I.","zh": "好的，我叫 Wei，拼写是 W-E-I。"},{"who": "A","en": "And a phone number we can reach you at?","zh": "再留一个能联系到您的电话？"},{"who": "B","en": "It's oh-one-two, three-four-five, six-seven-eight-nine.","zh": "号码是 012-345-6789。"},{"who": "A","en": "Great. So that's six people, Saturday at eight, under Wei.","zh": "好的。那就是六位，周六晚上八点，名字是 Wei。"},{"who": "B","en": "That's right. Could you also get two high chairs ready?","zh": "没错。能再帮我们准备两张儿童椅吗？"},{"who": "A","en": "No problem. We'll hold the table for fifteen minutes.","zh": "没问题。位子我们会保留十五分钟。"},{"who": "B","en": "Perfect. Thanks so much. See you on Saturday!","zh": "太好了，非常感谢。周六见！"}],"phrases": [["I'd like to make a reservation for ...","我想预订……；订餐厅、订位的开场句"],["There'll be six of us","我们一共六个人；也可以说 a table for six"],["if possible","如果可以的话；让要求听起来更客气"],["Eight works","八点可以；... works 表示这个时间或安排我OK"],["a table by the window","靠窗的桌子；by 在这里是旁边"],["a phone number we can reach you at","能联系到您的电话；reach 是联系上"],["under Wei","用 Wei 这个名字订的；到店时说 I have a reservation under Wei"],["hold the table","保留位子；常听到 We can only hold it for 15 minutes"]],"tip": "报人数说 There'll be four of us 或 a table for four；电话号码里的 0 一般读 oh，一位一位分组读，名字最好主动拼一遍。"},{"id": "airport_checkin","title": "机场柜台值机","en_title": "Checking In at the Airport","level": "基础","scene": "你在吉隆坡机场柜台办值机飞东京：托运行李、确认随身包、要一个靠窗座位，再问清登机口和时间。","roles": {"A": "值机柜台工作人员","B": "你（旅客）"},"lines": [{"who": "A","en": "Good morning. Where are you flying to today?","zh": "早上好。您今天飞去哪里？"},{"who": "B","en": "Morning. I'm flying to Tokyo. Here's my passport.","zh": "早。我飞东京。这是我的护照。"},{"who": "A","en": "Thank you. Are you checking in any bags?","zh": "谢谢。有行李要托运吗？"},{"who": "B","en": "Yes, just this one suitcase.","zh": "有，就这一个箱子。"},{"who": "A","en": "Please put it on the scale... Twenty-two kilos. That's fine.","zh": "请放到秤上……二十二公斤，没问题。"},{"who": "B","en": "Great. Can I bring this backpack as a carry-on?","zh": "好的。这个背包可以随身带上飞机吗？"},{"who": "A","en": "Yes, that's fine. Do you have any power banks in your suitcase?","zh": "可以。您箱子里有充电宝吗？"},{"who": "B","en": "Oh, I do. Should I take it out?","zh": "哦，有一个。需要拿出来吗？"},{"who": "A","en": "Yes, please. Power banks have to go in your carry-on.","zh": "是的，麻烦您。充电宝必须随身携带。"},{"who": "B","en": "Okay, got it. Also, is there a window seat available?","zh": "好，明白了。另外，还有靠窗的座位吗？"},{"who": "A","en": "Let me see... Yes, I can give you 24A.","zh": "我看看……有，可以给您 24A。"},{"who": "B","en": "Awesome, thanks. Which gate do I go to?","zh": "太好了，谢谢。我要去哪个登机口？"},{"who": "A","en": "Gate C12. Boarding starts at ten fifteen.","zh": "C12 登机口。十点十五分开始登机。"},{"who": "B","en": "And how long does it take to get to the gate?","zh": "走到登机口大概要多久？"},{"who": "A","en": "About fifteen minutes, so I'd head through security soon.","zh": "大概十五分钟，所以建议您尽快过安检。"},{"who": "B","en": "Will do. Thanks so much for your help.","zh": "好的。非常感谢您的帮助。"}],"phrases": [["Where are you flying to today?","您今天飞哪里？值机柜台的第一句"],["checking in any bags","托运行李；check in a bag 就是托运"],["carry-on","随身行李；Can I bring this as a carry-on?"],["Should I take it out?","需要拿出来吗？安检、值机都用得上"],["Is there a window seat available?","还有靠窗座位吗？靠过道是 aisle seat"],["Boarding starts at ...","几点开始登机；登机牌和广播里常见"],["How long does it take to get to ...?","去……要多久？问时间的万能句"],["head through security","去过安检；head 表示动身前往"]],"tip": "托运是 check in a bag，随身行李是 carry-on，靠窗 window seat、靠过道 aisle seat；充电宝不能托运，柜台常问 Any power banks or batteries?"},{"id": "hotel_problem","title": "酒店房间有问题要换房","en_title": "Asking to Change Hotel Rooms","level": "基础","scene": "你刚入住酒店，发现空调坏了，房间还挨着电梯很吵，你打电话给前台说明问题并要求换房。","roles": {"A": "酒店前台","B": "你（住客）"},"lines": [{"who": "A","en": "Good evening, front desk. How can I help?","zh": "晚上好，这里是前台。有什么可以帮您？"},{"who": "B","en": "Hi, I'm calling from room 1208. There's a problem with my room.","zh": "你好，我是 1208 房间的。我的房间有点问题。"},{"who": "A","en": "I'm sorry to hear that. What seems to be the problem?","zh": "很抱歉。请问是什么问题？"},{"who": "B","en": "The air conditioner isn't working. It's really hot in here.","zh": "空调不工作了。房间里特别热。"},{"who": "A","en": "I'm so sorry. I can send someone up to fix it right away.","zh": "非常抱歉。我马上派人上去修。"},{"who": "B","en": "Thanks, but it's also really noisy. My room is right next to the elevator.","zh": "谢谢，不过房间也很吵。我的房间就在电梯旁边。"},{"who": "A","en": "I see. Would you like to change rooms, then?","zh": "明白了。那您想换个房间吗？"},{"who": "B","en": "Yes, please. If possible, I'd like a quieter room on a higher floor.","zh": "是的，麻烦了。可以的话，我想要高一点楼层、安静一点的房间。"},{"who": "A","en": "Let me check... I have one on the twentieth floor. It's a bit smaller, though.","zh": "我查一下……二十楼有一间，不过稍微小一点。"},{"who": "B","en": "That's okay. As long as it's quiet, I'm happy.","zh": "没关系。只要安静就行。"},{"who": "A","en": "Great. I'll send someone up with a new key card to help with your bags.","zh": "好的。我派人带新房卡上去，顺便帮您拿行李。"},{"who": "B","en": "Perfect. How long will that take?","zh": "太好了。大概要多久？"},{"who": "A","en": "About ten minutes. Again, sorry for the trouble.","zh": "大约十分钟。再次抱歉给您添麻烦了。"},{"who": "B","en": "No worries. I really appreciate your help.","zh": "没事。非常感谢你的帮忙。"}],"phrases": [["I'm calling from room ...","我是……号房间的；打给前台先报房号"],["There's a problem with ...","……有点问题；投诉开场，语气平和"],["... isn't working","……坏了、不工作；比 is broken 更常用也更客气"],["right next to","紧挨着；right 用来强调"],["change rooms","换房间；注意 rooms 用复数"],["As long as ..., I'm happy","只要……我就满意；表达底线要求"],["Sorry for the trouble","抱歉添麻烦了；对方道歉或你麻烦别人时都能用"],["I really appreciate your help","非常感谢你的帮助；比 thank you 更正式、更真诚"]],"tip": "换房是 change rooms（rooms 一定是复数）；投诉时先客气说事实，再提具体要求，比如 I'd like a quieter room，比只抱怨有效得多。"},{"id": "asking_directions","title": "街上问路去 LRT 站","en_title": "Asking for Directions to the LRT","level": "入门","scene": "你在 Bangsar 街上找不到 LRT 站，一位本地路人主动帮你指路；学会问路，也顺便学会怎么给别人指路。","roles": {"A": "本地路人","B": "你"},"lines": [{"who": "A","en": "Hey, you look a little lost. Need some help?","zh": "嘿，你看起来有点迷路了。需要帮忙吗？"},{"who": "B","en": "Yeah, actually. Do you know how to get to the nearest LRT station?","zh": "是的，正好。你知道最近的 LRT 站怎么走吗？"},{"who": "A","en": "Sure. Where are you trying to go?","zh": "知道。你要去哪里？"},{"who": "B","en": "I'm trying to get to KL Sentral. I think Bangsar station is close.","zh": "我想去 KL Sentral。我记得 Bangsar 站就在附近。"},{"who": "A","en": "Yep, it is. Just go straight down this road for about two blocks.","zh": "对，很近。沿着这条路直走大概两个路口。"},{"who": "B","en": "Straight down this road. Okay, got it.","zh": "沿这条路直走。好的，明白了。"},{"who": "A","en": "Then turn left at the traffic light, right after the mamak.","zh": "然后在红绿灯左转，就在那家 mamak 档过去一点。"},{"who": "B","en": "Sorry, could you say that again a bit slower?","zh": "不好意思，你能说慢一点再讲一遍吗？"},{"who": "A","en": "No problem. Turn left at the traffic light, next to the mamak.","zh": "没问题。在红绿灯左转，就在 mamak 旁边。"},{"who": "B","en": "Okay. Is it far from here?","zh": "好的。离这里远吗？"},{"who": "A","en": "Not really. It's about a ten-minute walk.","zh": "不太远。走路大概十分钟。"},{"who": "B","en": "Is it easy to find, or should I just get a Grab?","zh": "好找吗？还是我直接叫个 Grab？"},{"who": "A","en": "Nah, you can't miss it. It's right across from a big petrol station.","zh": "不用，一眼就能看到。就在一个大加油站对面。"},{"who": "B","en": "Great. Can I pay with Touch 'n Go at the station?","zh": "太好了。车站可以用 Touch 'n Go 付吗？"},{"who": "A","en": "Yep, just tap your card at the gate.","zh": "可以，在闸机那里刷一下卡就行。"},{"who": "B","en": "Awesome. Thanks so much for your help!","zh": "太棒了。非常感谢你帮忙！"}],"phrases": [["You look a little lost","你看起来有点迷路；主动帮别人时的开场"],["Do you know how to get to ...?","你知道……怎么走吗？问路最常用的一句"],["Go straight down this road","沿着这条路直走；给别人指路的基本句"],["Turn left at the traffic light","在红绿灯左转；at 后面接路口、地标"],["Could you say that again a bit slower?","能说慢一点再讲一遍吗？听不懂时救命用"],["Is it far from here?","离这里远吗？"],["It's about a ten-minute walk","走路大约十分钟；注意 ten-minute 中间有连字符、minute 不加 s"],["You can't miss it","一眼就能看到、不会错过"]],"tip": "问路用 Do you know how to get to...? 开头，听不清别硬猜，直接说 Could you say that again a bit slower?；给别人指路记住三句：Go straight... / Turn left at... / It's right across from..."}],"functions": [{"id": "greetings","title": "👋 打招呼和回应","note": "How's it going? 这类问候不是真的在问近况，简单回一句再反问对方就行，不用认真汇报生活。","items": [{"en": "Hey, how's it going?","zh": "嘿，最近怎么样？","reg": "随意","ex": "A: Hey, how's it going? / B: Pretty good, you?","exzh": "A：嘿，最近怎么样？/ B：挺好的，你呢？"},{"en": "Pretty good, you?","zh": "挺好的，你呢？","reg": "随意","ex": "A: How are you doing? / B: Pretty good, you?","exzh": "A：你好吗？/ B：挺好的，你呢？"},{"en": "Not bad, not bad.","zh": "还行，还不错。","reg": "随意","ex": "A: How's work these days? / B: Not bad, not bad. Busy, but okay.","exzh": "A：最近工作怎么样？/ B：还行还行，忙，但还好。"},{"en": "What's up?","zh": "怎么了？/ 最近咋样？","reg": "随意","ex": "A: What's up? / B: Not much, just grabbing lunch.","exzh": "A：最近咋样？/ B：没啥，正去吃午饭。"},{"en": "Not much, what about you?","zh": "没什么特别的，你呢？","reg": "随意","ex": "A: What's new with you? / B: Not much, what about you?","exzh": "A：最近有什么新鲜事？/ B：没什么，你呢？"},{"en": "Can't complain.","zh": "挺好的，没什么可抱怨的。","reg": "随意","ex": "A: How's life in KL? / B: Can't complain. The food's amazing.","exzh": "A：在吉隆坡过得怎么样？/ B：挺好的，吃的太棒了。"},{"en": "Hanging in there.","zh": "还撑得住。（最近有点累或不顺）","reg": "随意","ex": "A: How are you holding up? / B: Hanging in there. Big deadline this week.","exzh": "A：你还好吗？/ B：还撑得住，这周有个大截止日期。"},{"en": "Long time no see!","zh": "好久不见！","reg": "随意","ex": "A: Long time no see! How have you been? / B: I've been good, thanks!","exzh": "A：好久不见！最近怎么样？/ B：挺好的，谢谢！"},{"en": "How have you been?","zh": "这段时间过得怎么样？","reg": "中性","ex": "A: Hey, how have you been? / B: Busy, but good. You?","exzh": "A：嘿，这段时间怎么样？/ B：忙，但挺好。你呢？"},{"en": "Good morning! How are you today?","zh": "早上好！今天怎么样？","reg": "中性","ex": "A: Good morning! How are you today? / B: I'm good, thanks. Just need coffee.","exzh": "A：早上好！今天怎么样？/ B：挺好，谢谢，就是需要杯咖啡。"},{"en": "Nice to meet you.","zh": "很高兴认识你。","reg": "中性","ex": "A: I'm Rui, I just joined the team. / B: Nice to meet you, Rui!","exzh": "A：我是 Rui，刚加入团队。/ B：很高兴认识你，Rui！"},{"en": "It's a pleasure to meet you.","zh": "非常荣幸认识您。","reg": "正式","ex": "A: This is our new client, Ms. Tan. / B: It's a pleasure to meet you.","exzh": "A：这是我们的新客户陈女士。/ B：非常荣幸认识您。"}]},{"id": "small_talk_open","title": "💬 开启闲聊","note": "从眼前的东西聊起最自然：天气、周末、吃的、对方在做的事；问开放式问题，别一上来问收入年龄。","items": [{"en": "Crazy weather today, huh?","zh": "今天天气真夸张，是吧？","reg": "随意","ex": "A: Crazy weather today, huh? / B: I know, it just started pouring out of nowhere.","exzh": "A：今天天气真夸张啊？/ B：是啊，突然就下大雨了。"},{"en": "Got any plans for the weekend?","zh": "周末有什么安排吗？","reg": "随意","ex": "A: Got any plans for the weekend? / B: Not really, maybe just chill at home.","exzh": "A：周末有安排吗？/ B：没什么，可能就在家躺着。"},{"en": "How was your weekend?","zh": "周末过得怎么样？","reg": "中性","ex": "A: How was your weekend? / B: Pretty relaxing. I went hiking on Saturday.","exzh": "A：周末过得怎么样？/ B：挺放松的，周六去爬山了。"},{"en": "So, what do you do?","zh": "那你是做什么工作的？","reg": "中性","ex": "A: So, what do you do? / B: I'm a software developer. How about you?","exzh": "A：那你是做什么的？/ B：我是程序员，你呢？"},{"en": "How do you know the host?","zh": "你和主人是怎么认识的？","reg": "中性","ex": "A: How do you know Jason? / B: We used to work together.","exzh": "A：你跟 Jason 怎么认识的？/ B：我们以前是同事。"},{"en": "Have you been here before?","zh": "你以前来过这儿吗？","reg": "中性","ex": "A: Have you been here before? / B: Yeah, their roti canai is the best.","exzh": "A：你以前来过这儿吗？/ B：来过，他们家的印度煎饼最好吃。"},{"en": "Is this your first time in KL?","zh": "这是你第一次来吉隆坡吗？","reg": "中性","ex": "A: Is this your first time in KL? / B: Yeah, I just landed yesterday.","exzh": "A：第一次来吉隆坡吗？/ B：对，昨天刚到。"},{"en": "I love your shirt. Where'd you get it?","zh": "我好喜欢你这件衬衫，在哪买的？","reg": "随意","ex": "A: I love your shirt. Where'd you get it? / B: Thanks! Just some random shop in Bangsar.","exzh": "A：你衬衫好好看，哪买的？/ B：谢谢！孟沙随便一家店。"},{"en": "Mind if I join you?","zh": "介意我坐这儿吗？/ 我可以加入吗？","reg": "中性","ex": "A: Mind if I join you? / B: Not at all, have a seat.","exzh": "A：介意我坐这儿吗？/ B：完全不介意，请坐。"},{"en": "Been busy lately?","zh": "最近忙吗？","reg": "随意","ex": "A: Been busy lately? / B: Super busy. We're launching next week.","exzh": "A：最近忙吗？/ B：超忙，我们下周上线。"},{"en": "Have you tried the food here?","zh": "你尝过这里的菜了吗？","reg": "中性","ex": "A: Have you tried the satay here? / B: Not yet. Is it good?","exzh": "A：你尝过这里的沙爹吗？/ B：还没，好吃吗？"}]},{"id": "end_conversation","title": "🚪 结束对话","note": "先给一个理由或信号（Anyway, I should...），再说再见，显得礼貌不突兀。","items": [{"en": "Anyway, I should get going.","zh": "好啦，我得走了。","reg": "随意","ex": "A: Anyway, I should get going. / B: Okay, see you around!","exzh": "A：好啦，我得走了。/ B：好，回头见！"},{"en": "I'll let you get back to it.","zh": "不打扰你了，你忙吧。","reg": "中性","ex": "A: Okay, I'll let you get back to it. / B: Thanks, talk later!","exzh": "A：好，不打扰你了，你忙。/ B：谢谢，回头聊！"},{"en": "It was great talking to you.","zh": "跟你聊天很开心。","reg": "中性","ex": "A: It was great talking to you. / B: You too! Let's keep in touch.","exzh": "A：跟你聊得很开心。/ B：我也是！保持联系。"},{"en": "Catch you later!","zh": "回头见！","reg": "随意","ex": "A: I gotta run. Catch you later! / B: Later!","exzh": "A：我得赶紧走了，回头见！/ B：拜！"},{"en": "I gotta run.","zh": "我得赶紧走了。","reg": "随意","ex": "A: Sorry, I gotta run, my Grab is here. / B: No worries, bye!","exzh": "A：抱歉我得走了，我的 Grab 到了。/ B：没事，拜！"},{"en": "Let's catch up soon.","zh": "改天再好好聊。","reg": "随意","ex": "A: Let's catch up soon. / B: Definitely. Text me.","exzh": "A：改天再聊。/ B：一定，给我发消息。"},{"en": "Talk to you later.","zh": "回头再聊。","reg": "随意","ex": "A: Okay, talk to you later. / B: Yep, bye!","exzh": "A：好，回头聊。/ B：嗯，拜！"},{"en": "Take care!","zh": "保重！","reg": "中性","ex": "A: See you next week. / B: Take care!","exzh": "A：下周见。/ B：保重！"},{"en": "Have a good one!","zh": "祝你今天愉快！","reg": "随意","ex": "A: Thanks for your help. / B: No problem, have a good one!","exzh": "A：谢谢帮忙。/ B：不客气，祝你愉快！"},{"en": "I won't keep you any longer.","zh": "就不多耽误你时间了。","reg": "中性","ex": "A: I won't keep you any longer. / B: Thanks, it was nice chatting.","exzh": "A：不多耽误你了。/ B：谢谢，聊得很开心。"},{"en": "Thank you for your time today.","zh": "感谢您今天抽出时间。","reg": "正式","ex": "A: Thank you for your time today. / B: My pleasure. I'll follow up by email.","exzh": "A：感谢您今天抽时间。/ B：不客气，我会邮件跟进。"}]},{"id": "clarify","title": "👂 没听清 / 请对方重复和澄清","note": "没听懂很正常，直接说出来比瞎猜好；用 Sorry? 或复述对方的话来确认，母语者也常这么做。","items": [{"en": "Sorry?","zh": "不好意思，你说什么？","reg": "随意","ex": "A: Do you want a bag? / B: Sorry? / A: A bag, for your stuff?","exzh": "A：要袋子吗？/ B：不好意思？/ A：袋子，装东西的？"},{"en": "Sorry, what was that?","zh": "抱歉，刚才你说什么？","reg": "随意","ex": "A: We're moving it to Thursday. / B: Sorry, what was that?","exzh": "A：我们改到周四了。/ B：抱歉，你说啥？"},{"en": "Could you say that again?","zh": "你能再说一遍吗？","reg": "中性","ex": "A: The code is 4-7-2-9. / B: Could you say that again?","exzh": "A：密码是 4729。/ B：能再说一遍吗？"},{"en": "I didn't quite catch that.","zh": "我没太听清。","reg": "中性","ex": "Sorry, I didn't quite catch that. The music's really loud.","exzh": "抱歉我没太听清，音乐太吵了。"},{"en": "What do you mean?","zh": "你是什么意思？","reg": "中性","ex": "A: That idea is kind of a long shot. / B: What do you mean?","exzh": "A：那个想法有点悬。/ B：什么意思？"},{"en": "So you're saying...?","zh": "所以你的意思是……？","reg": "中性","ex": "So you're saying we need to redo the whole thing?","exzh": "所以你的意思是我们要全部重做？"},{"en": "Could you slow down a little?","zh": "你能说慢一点吗？","reg": "中性","ex": "Sorry, could you slow down a little? My English isn't that fast.","exzh": "抱歉，你能说慢点吗？我英语反应没那么快。"},{"en": "Wait, you lost me.","zh": "等等，我没跟上。","reg": "随意","ex": "Wait, you lost me. Who's Mark again?","exzh": "等等，我没跟上，Mark 是谁来着？"},{"en": "Just to make sure I understand...","zh": "我确认一下我理解得对不对……","reg": "中性","ex": "Just to make sure I understand, the deadline is Friday, right?","exzh": "我确认一下，截止日期是周五，对吧？"},{"en": "How do you spell that?","zh": "这个怎么拼？","reg": "中性","ex": "A: My name is Siobhan. / B: Sorry, how do you spell that?","exzh": "A：我叫 Siobhan。/ B：抱歉，怎么拼？"},{"en": "What does that mean?","zh": "那是什么意思？","reg": "中性","ex": "A: Let's not boil the ocean. / B: Haha, what does that mean?","exzh": "A：别想一口吃成胖子。/ B：哈哈，那是什么意思？"},{"en": "Could you clarify what you mean by that?","zh": "您能具体说明一下这是什么意思吗？","reg": "正式","ex": "Could you clarify what you mean by a phased rollout?","exzh": "您能具体说明一下分阶段上线是指什么吗？"}]},{"id": "fillers","title": "⏳ 争取思考时间（填充词）","note": "一时想不出词时，用这些代替沉默或嗯嗯啊啊，听起来更自然；但别每句都用。","items": [{"en": "Um, let me think.","zh": "嗯，我想想。","reg": "随意","ex": "A: What's your favorite movie? / B: Um, let me think.","exzh": "A：你最喜欢哪部电影？/ B：嗯，我想想。"},{"en": "Well...","zh": "嗯……这个嘛……","reg": "随意","ex": "A: Did you like it? / B: Well... it was okay, I guess.","exzh": "A：你喜欢吗？/ B：这个嘛……还行吧。"},{"en": "Hmm, good question.","zh": "嗯，好问题。","reg": "中性","ex": "A: Why did you choose this job? / B: Hmm, good question.","exzh": "A：你为什么选这份工作？/ B：嗯，好问题。"},{"en": "How do I put this?","zh": "怎么说呢？","reg": "随意","ex": "How do I put this? He's nice, but kind of hard to work with.","exzh": "怎么说呢？他人挺好，但不太好合作。"},{"en": "You know what I mean?","zh": "你懂我意思吧？","reg": "随意","ex": "It's not bad, it's just not for me, you know what I mean?","exzh": "不是不好，就是不适合我，你懂我意思吧？"},{"en": "Let me see...","zh": "我看看……","reg": "中性","ex": "Let me see... I think I can make it by seven.","exzh": "我看看……我觉得七点前能到。"},{"en": "It's like...","zh": "就像是……","reg": "随意","ex": "It's like, you work all day and still feel behind.","exzh": "就像是，你干了一整天还是觉得进度落后。"},{"en": "What's the word?","zh": "那个词叫什么来着？","reg": "随意","ex": "It's kind of, what's the word, overwhelming?","exzh": "有点，那个词叫啥来着，让人喘不过气？"},{"en": "That's a tough one.","zh": "这个问题有点难。","reg": "随意","ex": "A: Nasi lemak or char kuey teow? / B: Oh, that's a tough one.","exzh": "A：椰浆饭还是炒粿条？/ B：哇，这个好难选。"},{"en": "I mean...","zh": "我是说……","reg": "随意","ex": "I mean, it's expensive, but it's worth it.","exzh": "我是说，是贵，但值得。"},{"en": "Give me a sec.","zh": "给我一秒钟。","reg": "随意","ex": "A: What's the Wi-Fi password? / B: Give me a sec, I'll check.","exzh": "A：Wi-Fi 密码是什么？/ B：等一下，我查查。"},{"en": "That's an interesting question. Let me think about it.","zh": "这个问题很有意思，我想一下。","reg": "正式","ex": "That's an interesting question. Let me think about it for a moment.","exzh": "这个问题很有意思，让我想一下。"}]},{"id": "opinions","title": "🧠 表达观点","note": "用 I think / To me 开头让观点听起来更柔和；美国人常把意见包装成个人感受，不说绝对的话。","items": [{"en": "I think...","zh": "我觉得……","reg": "中性","ex": "I think we should leave early to avoid the traffic.","exzh": "我觉得我们应该早点走，避开堵车。"},{"en": "If you ask me...","zh": "要我说的话……","reg": "随意","ex": "If you ask me, the old version was better.","exzh": "要我说，旧版本更好。"},{"en": "Honestly,...","zh": "说实话……","reg": "随意","ex": "Honestly, I don't think it's worth the money.","exzh": "说实话，我觉得不值这个钱。"},{"en": "To me,...","zh": "对我来说……","reg": "中性","ex": "To me, a good commute matters more than a big condo.","exzh": "对我来说，通勤方便比大公寓更重要。"},{"en": "The way I see it,...","zh": "在我看来……","reg": "中性","ex": "The way I see it, we don't have much choice.","exzh": "在我看来，我们没太多选择。"},{"en": "I feel like...","zh": "我感觉……","reg": "随意","ex": "I feel like this meeting could've been an email.","exzh": "我感觉这个会发封邮件就够了。"},{"en": "Personally, I'd go with...","zh": "我个人会选……","reg": "中性","ex": "Personally, I'd go with the cheaper option.","exzh": "我个人会选便宜的那个。"},{"en": "I'm pretty sure...","zh": "我挺确定……","reg": "随意","ex": "I'm pretty sure the LRT is faster at this hour.","exzh": "我挺确定这个点坐 LRT 更快。"},{"en": "I'm not a fan of...","zh": "我不太喜欢……","reg": "随意","ex": "I'm not a fan of open-plan offices.","exzh": "我不太喜欢开放式办公室。"},{"en": "It seems to me that...","zh": "在我看来似乎……","reg": "中性","ex": "It seems to me that the users just want it simpler.","exzh": "在我看来，用户就是想要更简单。"},{"en": "From my perspective,...","zh": "从我的角度来看……","reg": "正式","ex": "From my perspective, the main risk is the timeline.","exzh": "从我的角度看，主要风险是时间线。"}]},{"id": "agree","title": "👍 同意","note": "同意时加点热情会更自然；Exactly 和 Totally 是美式口语里最高频的两个。","items": [{"en": "Yeah, totally.","zh": "对，完全同意。","reg": "随意","ex": "A: That was way too long. / B: Yeah, totally.","exzh": "A：那也太长了。/ B：对，完全是。"},{"en": "Exactly!","zh": "就是！没错！","reg": "随意","ex": "A: So we just need to fix the login first? / B: Exactly!","exzh": "A：所以先修登录就行？/ B：没错！"},{"en": "I know, right?","zh": "就是说嘛！","reg": "随意","ex": "A: The traffic today was insane. / B: I know, right?","exzh": "A：今天堵车太夸张了。/ B：就是说嘛！"},{"en": "Same here.","zh": "我也是。","reg": "随意","ex": "A: I'm so tired. / B: Same here.","exzh": "A：我好累。/ B：我也是。"},{"en": "Tell me about it.","zh": "可不是嘛。（深有同感）","reg": "随意","ex": "A: Rent in KLCC is crazy. / B: Tell me about it.","exzh": "A：KLCC 的房租太离谱了。/ B：可不是嘛。"},{"en": "That's a good point.","zh": "说得有道理。","reg": "中性","ex": "A: We should test it on mobile too. / B: That's a good point.","exzh": "A：我们也该在手机上测一下。/ B：有道理。"},{"en": "I couldn't agree more.","zh": "我再同意不过了。","reg": "中性","ex": "A: We need more time for testing. / B: I couldn't agree more.","exzh": "A：我们需要更多测试时间。/ B：太同意了。"},{"en": "You're right.","zh": "你说得对。","reg": "中性","ex": "You're right, I should've checked first.","exzh": "你说得对，我应该先检查一下。"},{"en": "Fair enough.","zh": "也是，说得过去。","reg": "随意","ex": "A: I'd rather not drive in this rain. / B: Fair enough.","exzh": "A：这么大雨我不想开车。/ B：也是。"},{"en": "Sounds good to me.","zh": "我觉得可以。","reg": "随意","ex": "A: Let's meet at eight? / B: Sounds good to me.","exzh": "A：八点见？/ B：可以。"},{"en": "I'm with you on that.","zh": "这点我跟你一样。","reg": "中性","ex": "I'm with you on that. The design needs more work.","exzh": "这点我同意你，设计还需要改。"},{"en": "I completely agree with you.","zh": "我完全同意您的看法。","reg": "正式","ex": "I completely agree with you. Security should come first.","exzh": "我完全同意，安全应该放第一位。"}]},{"id": "disagree","title": "🙅 不同意（委婉）","note": "先肯定一点再提不同（I see your point, but...），或用问题代替直接否定，避免说 You're wrong。","items": [{"en": "I'm not so sure about that.","zh": "这个我不太确定哦。","reg": "中性","ex": "A: Everyone will love it. / B: Hmm, I'm not so sure about that.","exzh": "A：大家都会喜欢的。/ B：嗯，这个我不太确定。"},{"en": "I see your point, but...","zh": "我明白你的意思，但……","reg": "中性","ex": "I see your point, but I think it's too risky right now.","exzh": "我明白你的意思，但我觉得现在风险太大。"},{"en": "I don't know, man.","zh": "我觉得不一定吧，哥们。","reg": "随意","ex": "A: Let's just skip testing. / B: I don't know, man. That sounds risky.","exzh": "A：干脆不测了。/ B：不好吧，听着有风险。"},{"en": "That's true, but...","zh": "确实，但是……","reg": "中性","ex": "That's true, but it's also way more expensive.","exzh": "确实，但也贵得多。"},{"en": "I'm not sure I agree.","zh": "我不太确定我同意。","reg": "中性","ex": "I'm not sure I agree. Users seemed to like the old layout.","exzh": "我不太同意，用户好像喜欢旧布局。"},{"en": "I kind of see it differently.","zh": "我看法有点不一样。","reg": "随意","ex": "I kind of see it differently. I think timing was the real problem.","exzh": "我看法有点不同，我觉得真正的问题是时机。"},{"en": "Not necessarily.","zh": "不一定。","reg": "中性","ex": "A: Bigger teams move faster. / B: Not necessarily.","exzh": "A：团队越大越快。/ B：不一定。"},{"en": "Are you sure about that?","zh": "你确定吗？","reg": "随意","ex": "A: The mall closes at six. / B: Are you sure about that? I think it's ten.","exzh": "A：商场六点关门。/ B：你确定吗？我记得是十点。"},{"en": "I hear you, but...","zh": "我懂你的意思，但……","reg": "随意","ex": "I hear you, but we really can't push the date again.","exzh": "我懂，但我们真的不能再推迟了。"},{"en": "Have you thought about...?","zh": "你有没有考虑过……？","reg": "中性","ex": "Have you thought about taking the LRT instead?","exzh": "你有没有想过改坐 LRT？"},{"en": "I'm afraid I have to disagree.","zh": "恐怕我不能同意。","reg": "正式","ex": "I'm afraid I have to disagree. The data shows the opposite.","exzh": "恐怕我不能同意，数据显示正好相反。"},{"en": "I respect that, but I have a different view.","zh": "我尊重你的看法，但我有不同观点。","reg": "正式","ex": "I respect that, but I have a different view on the budget.","exzh": "我尊重这个看法，但对预算我有不同观点。"}]},{"id": "reactions","title": "😮 表示感兴趣和回应","note": "听别人说话时不断给反应（Really? / Oh nice!），对方会觉得你在认真听；语调要有起伏。","items": [{"en": "Really?","zh": "真的吗？","reg": "随意","ex": "A: I'm moving to Penang. / B: Really? When?","exzh": "A：我要搬去槟城了。/ B：真的？什么时候？"},{"en": "No way!","zh": "不会吧！","reg": "随意","ex": "A: I got the job! / B: No way! Congrats!","exzh": "A：我拿到工作了！/ B：不会吧！恭喜！"},{"en": "That makes sense.","zh": "这说得通。/ 明白了。","reg": "中性","ex": "A: It was slow because of the cache. / B: Ah, that makes sense.","exzh": "A：慢是因为缓存。/ B：啊，这说得通。"},{"en": "Oh, nice!","zh": "哦，不错啊！","reg": "随意","ex": "A: I finally passed my driving test. / B: Oh, nice!","exzh": "A：我终于考过驾照了。/ B：哦，不错啊！"},{"en": "Oh, I see.","zh": "哦，我明白了。","reg": "中性","ex": "A: She's off today, she's sick. / B: Oh, I see.","exzh": "A：她今天请假了，生病了。/ B：哦，这样啊。"},{"en": "That's awesome!","zh": "太棒了！","reg": "随意","ex": "A: We're going to Japan next month. / B: That's awesome!","exzh": "A：我们下个月去日本。/ B：太棒了！"},{"en": "Oh no, that sucks.","zh": "哦不，那太惨了。","reg": "随意","ex": "A: My flight got canceled. / B: Oh no, that sucks.","exzh": "A：我航班取消了。/ B：哦不，太惨了。"},{"en": "Seriously?","zh": "认真的吗？","reg": "随意","ex": "A: He quit after two days. / B: Seriously?","exzh": "A：他干了两天就辞职了。/ B：认真的？"},{"en": "Wait, what happened?","zh": "等等，发生什么了？","reg": "随意","ex": "A: So the whole server went down. / B: Wait, what happened?","exzh": "A：然后整个服务器挂了。/ B：等等，怎么回事？"},{"en": "And then what?","zh": "然后呢？","reg": "随意","ex": "A: So I called him three times. / B: And then what?","exzh": "A：我给他打了三次电话。/ B：然后呢？"},{"en": "That's so interesting.","zh": "好有意思。","reg": "中性","ex": "A: In my hometown, we eat noodles on birthdays. / B: That's so interesting.","exzh": "A：我老家过生日吃面。/ B：好有意思。"},{"en": "I had no idea.","zh": "我完全不知道。","reg": "中性","ex": "A: Durian is banned on the trains. / B: Haha, I had no idea.","exzh": "A：榴莲不准带上火车。/ B：哈哈，我完全不知道。"}]},{"id": "thanks","title": "🙏 感谢和回应","note": "回应感谢时美国人常说 No problem / You bet，比 You're welcome 更轻松；正式场合再用 My pleasure。","items": [{"en": "Thanks a lot!","zh": "多谢！","reg": "随意","ex": "A: Here's your coffee. / B: Thanks a lot!","exzh": "A：你的咖啡。/ B：多谢！"},{"en": "No problem.","zh": "没问题，不客气。","reg": "随意","ex": "A: Thanks for the ride. / B: No problem.","exzh": "A：谢谢载我。/ B：不客气。"},{"en": "I really appreciate it.","zh": "真的很感谢。","reg": "中性","ex": "Thanks for staying late. I really appreciate it.","exzh": "谢谢你留下来加班，真的很感谢。"},{"en": "You're a lifesaver!","zh": "你真是救星！","reg": "随意","ex": "A: I brought you an umbrella. / B: You're a lifesaver!","exzh": "A：给你带了把伞。/ B：你真是救星！"},{"en": "Anytime.","zh": "随时都行。","reg": "随意","ex": "A: Thanks for helping me move. / B: Anytime.","exzh": "A：谢谢帮我搬家。/ B：随时找我。"},{"en": "Don't mention it.","zh": "别客气。","reg": "随意","ex": "A: Thanks for covering for me. / B: Don't mention it.","exzh": "A：谢谢帮我顶班。/ B：别客气。"},{"en": "Thanks, I owe you one.","zh": "谢啦，欠你一个人情。","reg": "随意","ex": "Thanks for fixing my bug. I owe you one.","exzh": "谢谢帮我修 bug，欠你一次。"},{"en": "You bet.","zh": "当然，不客气。","reg": "随意","ex": "A: Thanks for the tip! / B: You bet.","exzh": "A：谢谢你的建议！/ B：不客气。"},{"en": "That's so nice of you.","zh": "你真好。","reg": "中性","ex": "You got me a gift? That's so nice of you.","exzh": "你给我买了礼物？你真好。"},{"en": "Thanks for having me.","zh": "谢谢你们的招待。","reg": "中性","ex": "Thanks for having me. Dinner was amazing.","exzh": "谢谢招待，晚饭太好吃了。"},{"en": "My pleasure.","zh": "这是我的荣幸。/ 乐意效劳。","reg": "正式","ex": "A: Thank you for the presentation. / B: My pleasure.","exzh": "A：感谢您的分享。/ B：乐意之至。"},{"en": "Thank you for your help with this.","zh": "感谢您在这件事上的帮助。","reg": "正式","ex": "Thank you for your help with this. It made a big difference.","exzh": "感谢您的帮助，真的帮了大忙。"}]},{"id": "apologies","title": "😓 道歉和回应","note": "小事一句 My bad 就行；大事要说清楚原因和补救。回应道歉常用 No worries / It's okay。","items": [{"en": "Sorry about that.","zh": "那个不好意思啊。","reg": "中性","ex": "Oh, I sent you the wrong file. Sorry about that.","exzh": "哦，我发错文件了，不好意思。"},{"en": "My bad.","zh": "我的锅。","reg": "随意","ex": "A: You took my seat. / B: Oh, my bad!","exzh": "A：你坐了我的位子。/ B：哦，我的错！"},{"en": "No worries.","zh": "没事，别担心。","reg": "随意","ex": "A: Sorry I'm late. / B: No worries, we just started.","exzh": "A：抱歉我迟到了。/ B：没事，刚开始。"},{"en": "Sorry I'm late.","zh": "抱歉我迟到了。","reg": "中性","ex": "Sorry I'm late. The Grab took forever.","exzh": "抱歉迟到了，Grab 等了好久。"},{"en": "It's okay, don't worry about it.","zh": "没关系，别放在心上。","reg": "中性","ex": "A: I broke your mug. / B: It's okay, don't worry about it.","exzh": "A：我把你杯子打碎了。/ B：没关系，别在意。"},{"en": "I didn't mean to.","zh": "我不是故意的。","reg": "随意","ex": "Sorry, I didn't mean to interrupt.","exzh": "抱歉，我不是故意打断你的。"},{"en": "I feel terrible about this.","zh": "这事我很过意不去。","reg": "中性","ex": "I totally forgot your birthday. I feel terrible about this.","exzh": "我完全忘了你生日，太过意不去了。"},{"en": "It won't happen again.","zh": "不会再有下次了。","reg": "中性","ex": "Sorry for missing the call. It won't happen again.","exzh": "抱歉错过电话，不会再有下次了。"},{"en": "It's all good.","zh": "完全没事。","reg": "随意","ex": "A: Sorry for the mess. / B: It's all good.","exzh": "A：抱歉弄得乱糟糟。/ B：完全没事。"},{"en": "Excuse me, sorry.","zh": "不好意思，借过。","reg": "中性","ex": "Excuse me, sorry, can I get past?","exzh": "不好意思，能让我过一下吗？"},{"en": "I apologize for the inconvenience.","zh": "给您带来不便，非常抱歉。","reg": "正式","ex": "I apologize for the inconvenience. We're fixing it now.","exzh": "给您带来不便很抱歉，我们正在修复。"},{"en": "Apology accepted.","zh": "我接受你的道歉。","reg": "正式","ex": "A: I'm really sorry about yesterday. / B: Apology accepted. Let's move on.","exzh": "A：昨天的事真的很抱歉。/ B：接受道歉，翻篇吧。"}]},{"id": "ask_help","title": "🆘 请求帮忙","note": "先用 Could you / Would you mind 软化语气；Would you mind 后面接动词 -ing，同意时要回 Not at all。","items": [{"en": "Can you give me a hand?","zh": "能帮我一把吗？","reg": "随意","ex": "Can you give me a hand with these boxes?","exzh": "能帮我搬一下这些箱子吗？"},{"en": "Could you help me with something?","zh": "你能帮我个忙吗？","reg": "中性","ex": "Hey, could you help me with something real quick?","exzh": "嘿，能快速帮我个忙吗？"},{"en": "Do you have a minute?","zh": "你有空一下吗？","reg": "中性","ex": "Do you have a minute? I want to ask about the API.","exzh": "你有空吗？我想问下 API 的事。"},{"en": "Would you mind...?","zh": "你介意……吗？","reg": "中性","ex": "Would you mind closing the window? It's a bit cold.","exzh": "你介意关一下窗吗？有点冷。"},{"en": "Can I ask you a favor?","zh": "能请你帮个忙吗？","reg": "随意","ex": "Can I ask you a favor? Could you water my plants this weekend?","exzh": "能帮个忙吗？周末帮我浇下花？"},{"en": "I'm kind of stuck here.","zh": "我这儿有点卡住了。","reg": "随意","ex": "I'm kind of stuck here. Can you take a look?","exzh": "我这有点卡住了，你能看看吗？"},{"en": "Could you take a look at this?","zh": "你能看一下这个吗？","reg": "中性","ex": "Could you take a look at this before I push it?","exzh": "我提交前你能帮我看一下吗？"},{"en": "Do you know how to...?","zh": "你知道怎么……吗？","reg": "中性","ex": "Do you know how to top up a Touch 'n Go card?","exzh": "你知道 Touch 'n Go 卡怎么充值吗？"},{"en": "I was wondering if you could...","zh": "我在想你能不能……","reg": "中性","ex": "I was wondering if you could review my PR today.","exzh": "我在想你今天能不能帮我看下 PR。"},{"en": "Sure, what do you need?","zh": "当然，需要什么？","reg": "随意","ex": "A: Got a sec? / B: Sure, what do you need?","exzh": "A：有空吗？/ B：当然，要啥？"},{"en": "Would it be possible to...?","zh": "是否有可能……？","reg": "正式","ex": "Would it be possible to extend the deadline by two days?","exzh": "截止日期能否延后两天？"},{"en": "I'd really appreciate your help with this.","zh": "如果您能帮忙我会非常感激。","reg": "正式","ex": "I'd really appreciate your help with this report.","exzh": "这份报告如果您能帮忙我会非常感激。"}]},{"id": "suggestions","title": "💡 提建议","note": "美式口语提建议常用问句（Why don't we...? / How about...?），比 You should 更不强势。","items": [{"en": "How about...?","zh": "……怎么样？","reg": "随意","ex": "How about mamak tonight?","exzh": "今晚去嘛嘛档怎么样？"},{"en": "Why don't we...?","zh": "我们为什么不……？/ 要不我们……","reg": "中性","ex": "Why don't we take a break and come back later?","exzh": "要不我们休息一下，晚点再弄？"},{"en": "Let's...","zh": "我们……吧。","reg": "随意","ex": "Let's just order in. It's raining.","exzh": "叫外卖吧，在下雨。"},{"en": "Maybe we could...","zh": "也许我们可以……","reg": "中性","ex": "Maybe we could split the task into smaller parts.","exzh": "也许我们可以把任务拆小一点。"},{"en": "You should totally...","zh": "你真的应该……","reg": "随意","ex": "You should totally try the cendol here.","exzh": "你一定要试试这里的煎蕊。"},{"en": "What if we...?","zh": "如果我们……会怎样？","reg": "中性","ex": "What if we launch it to ten percent of users first?","exzh": "如果我们先给百分之十的用户上线呢？"},{"en": "Have you tried...?","zh": "你试过……吗？","reg": "中性","ex": "Have you tried restarting it?","exzh": "你试过重启吗？"},{"en": "If I were you, I'd...","zh": "如果我是你，我会……","reg": "中性","ex": "If I were you, I'd get a condo near the LRT.","exzh": "如果我是你，我会租靠近 LRT 的公寓。"},{"en": "It might be a good idea to...","zh": "……可能是个好主意。","reg": "中性","ex": "It might be a good idea to back up your files first.","exzh": "先备份文件可能比较好。"},{"en": "Want to...?","zh": "要不要……？","reg": "随意","ex": "Want to grab a coffee after this?","exzh": "这个结束后要不要去喝杯咖啡？"},{"en": "I'd suggest...","zh": "我建议……","reg": "正式","ex": "I'd suggest we review the numbers before deciding.","exzh": "我建议我们决定前先看一下数据。"},{"en": "Might I suggest an alternative?","zh": "我可以提个替代方案吗？","reg": "正式","ex": "Might I suggest an alternative? We could use a vendor.","exzh": "我能提个替代方案吗？我们可以找外包。"}]},{"id": "invitations","title": "🎉 邀请和接受 / 拒绝","note": "拒绝时先表示感谢或遗憾，给个简短理由，最好再提议下次（Maybe next time?），别只说 No。","items": [{"en": "Are you free on Saturday?","zh": "你周六有空吗？","reg": "随意","ex": "Are you free on Saturday? We're doing a barbecue.","exzh": "你周六有空吗？我们要烧烤。"},{"en": "Do you want to come?","zh": "你想一起来吗？","reg": "随意","ex": "We're going to see a movie. Do you want to come?","exzh": "我们要去看电影，你想一起吗？"},{"en": "I'd love to!","zh": "我很乐意！","reg": "中性","ex": "A: Want to join us for dinner? / B: I'd love to!","exzh": "A：一起吃晚饭吗？/ B：好呀！"},{"en": "Count me in!","zh": "算我一个！","reg": "随意","ex": "A: We're playing futsal tonight. / B: Count me in!","exzh": "A：今晚踢五人足球。/ B：算我一个！"},{"en": "Sounds fun! What time?","zh": "听起来好玩！几点？","reg": "随意","ex": "A: Karaoke on Friday? / B: Sounds fun! What time?","exzh": "A：周五去唱K？/ B：好玩！几点？"},{"en": "I wish I could, but...","zh": "我也想去，可是……","reg": "中性","ex": "I wish I could, but I already have plans.","exzh": "我也想去，可是我已经有安排了。"},{"en": "Can I take a rain check?","zh": "能改天吗？","reg": "随意","ex": "I'm super tired tonight. Can I take a rain check?","exzh": "我今晚太累了，能改天吗？"},{"en": "Maybe next time.","zh": "下次吧。","reg": "随意","ex": "I can't make it this week. Maybe next time?","exzh": "这周去不了，下次吧？"},{"en": "Let me check and get back to you.","zh": "我看看再回复你。","reg": "中性","ex": "Let me check my schedule and get back to you.","exzh": "我看下日程再回你。"},{"en": "I'm not really feeling it tonight.","zh": "我今晚不太想去。","reg": "随意","ex": "Thanks, but I'm not really feeling it tonight.","exzh": "谢谢，不过我今晚不太想出门。"},{"en": "We'd love to have you join us.","zh": "非常欢迎你加入我们。","reg": "正式","ex": "We're having a team dinner. We'd love to have you join us.","exzh": "我们有个团队晚餐，很欢迎你来。"},{"en": "Thank you for the invitation, but I'm unable to attend.","zh": "感谢邀请，但我无法出席。","reg": "正式","ex": "Thank you for the invitation, but I'm unable to attend on Friday.","exzh": "感谢邀请，但我周五无法出席。"}]},{"id": "storytelling","title": "📖 讲故事的衔接","note": "讲经历时用这些词把情节串起来，听起来像母语者在聊天；So 和 Anyway 是最常用的。","items": [{"en": "So, get this.","zh": "听好了，你猜怎么着。","reg": "随意","ex": "So, get this. My landlord just raised the rent again.","exzh": "你猜怎么着，我房东又涨房租了。"},{"en": "So anyway,...","zh": "总之呢……（回到正题）","reg": "随意","ex": "So anyway, we finally got to the airport.","exzh": "总之，我们最后到了机场。"},{"en": "Long story short,...","zh": "长话短说……","reg": "随意","ex": "Long story short, I missed my flight.","exzh": "长话短说，我误机了。"},{"en": "You'll never guess what happened.","zh": "你绝对猜不到发生了什么。","reg": "随意","ex": "You'll never guess what happened at work today.","exzh": "你绝对猜不到今天公司发生了什么。"},{"en": "And then, out of nowhere,...","zh": "然后突然之间……","reg": "随意","ex": "And then, out of nowhere, it started pouring.","exzh": "然后突然就下起了大雨。"},{"en": "The thing is,...","zh": "问题是……","reg": "随意","ex": "The thing is, nobody told me about the change.","exzh": "问题是，没人告诉我改了。"},{"en": "Turns out,...","zh": "结果发现……","reg": "随意","ex": "Turns out, the restaurant was closed on Mondays.","exzh": "结果发现那家餐厅周一不开。"},{"en": "Anyway, where was I?","zh": "对了，我说到哪了？","reg": "随意","ex": "Sorry, anyway, where was I? Oh right, the meeting.","exzh": "抱歉，我说到哪了？哦对，那个会。"},{"en": "At first,... but then...","zh": "一开始……但后来……","reg": "中性","ex": "At first, I hated KL traffic, but then I got used to it.","exzh": "一开始我很讨厌吉隆坡的交通，后来就习惯了。"},{"en": "To make a long story short,...","zh": "简单来说……","reg": "中性","ex": "To make a long story short, we got the contract.","exzh": "简单来说，我们拿下了合同。"},{"en": "In the end,...","zh": "最后……","reg": "中性","ex": "In the end, it all worked out.","exzh": "最后一切都顺利了。"},{"en": "Believe it or not,...","zh": "信不信由你……","reg": "随意","ex": "Believe it or not, I've never had durian.","exzh": "信不信由你，我从来没吃过榴莲。"}]},{"id": "feelings","title": "❤️ 表达感受和情绪","note": "用 I'm so... / I'm kind of... 调节程度；美国人常用 kind of、a little 让负面情绪听起来不那么重。","items": [{"en": "I'm so excited!","zh": "我好激动！","reg": "随意","ex": "I'm so excited! We're going to Bali next week.","exzh": "好激动！我们下周去巴厘岛。"},{"en": "I'm kind of stressed out.","zh": "我有点压力大。","reg": "随意","ex": "I'm kind of stressed out about the release.","exzh": "我对这次上线有点压力大。"},{"en": "I'm exhausted.","zh": "我累死了。","reg": "随意","ex": "I'm exhausted. I just want to sleep.","exzh": "我累死了，只想睡觉。"},{"en": "That made my day!","zh": "那让我开心了一整天！","reg": "随意","ex": "My boss said great job. That made my day!","exzh": "老板说我干得好，开心一整天！"},{"en": "I'm a little nervous.","zh": "我有点紧张。","reg": "中性","ex": "I'm a little nervous about the interview tomorrow.","exzh": "我对明天的面试有点紧张。"},{"en": "I'm over the moon.","zh": "我开心坏了。","reg": "随意","ex": "She said yes! I'm over the moon.","exzh": "她答应了！我开心坏了。"},{"en": "I'm so frustrated.","zh": "我好烦，好受挫。","reg": "中性","ex": "I'm so frustrated. This bug keeps coming back.","exzh": "好烦，这个 bug 一直反复出现。"},{"en": "I'm not feeling great today.","zh": "我今天状态不太好。","reg": "中性","ex": "I'm not feeling great today. I think I'll work from home.","exzh": "我今天不太舒服，打算在家办公。"},{"en": "I'm kind of bummed.","zh": "我有点失落。","reg": "随意","ex": "I'm kind of bummed the concert got canceled.","exzh": "演唱会取消了我有点失落。"},{"en": "It really gets on my nerves.","zh": "这真让我心烦。","reg": "随意","ex": "When people talk loudly on the LRT, it really gets on my nerves.","exzh": "有人在 LRT 上大声讲话真让我心烦。"},{"en": "I'm relieved.","zh": "我松了口气。","reg": "中性","ex": "The test passed. I'm so relieved.","exzh": "测试通过了，我松了一大口气。"},{"en": "I'm really grateful for this.","zh": "我对此真的很感激。","reg": "正式","ex": "I'm really grateful for this opportunity.","exzh": "我真的很感激这次机会。"}]},{"id": "complaints","title": "😤 抱怨（礼貌）","note": "对店家或同事抱怨时，先说事实再提请求，语气平和更有效；用 I'm afraid / There seems to be 软化。","items": [{"en": "Excuse me, I think there's a problem with my order.","zh": "不好意思，我的单好像有点问题。","reg": "中性","ex": "Excuse me, I think there's a problem with my order. I asked for no ice.","exzh": "不好意思，我的单好像有问题，我说了去冰。"},{"en": "This isn't what I ordered.","zh": "这不是我点的。","reg": "中性","ex": "Sorry, this isn't what I ordered. I got the chicken.","exzh": "抱歉，这不是我点的，我点的是鸡肉。"},{"en": "It's been like this for a while.","zh": "这情况已经有一阵子了。","reg": "中性","ex": "The aircon is leaking. It's been like this for a while.","exzh": "空调在漏水，已经有一阵子了。"},{"en": "I don't mean to complain, but...","zh": "我不是想抱怨，但是……","reg": "中性","ex": "I don't mean to complain, but the music is really loud.","exzh": "我不是想抱怨，但音乐真的太大声了。"},{"en": "Is there any way you could...?","zh": "有没有办法能……？","reg": "中性","ex": "Is there any way you could turn it down a bit?","exzh": "能不能稍微调小一点？"},{"en": "It's kind of annoying, to be honest.","zh": "说实话，有点烦人。","reg": "随意","ex": "It's kind of annoying, to be honest. The Wi-Fi keeps dropping.","exzh": "说实话挺烦的，Wi-Fi 老是断。"},{"en": "This is the third time this has happened.","zh": "这已经是第三次了。","reg": "中性","ex": "This is the third time this has happened this month.","exzh": "这个月这已经是第三次了。"},{"en": "I've been waiting for a while.","zh": "我已经等了好一会儿了。","reg": "中性","ex": "Sorry, I've been waiting for a while. Is my food coming?","exzh": "不好意思，我等了好一会儿了，我的菜快好了吗？"},{"en": "Ugh, I can't stand this.","zh": "呃，我受不了了。","reg": "随意","ex": "Ugh, I can't stand this traffic.","exzh": "呃，这堵车我受不了了。"},{"en": "Could I speak to the manager, please?","zh": "我可以和经理谈谈吗？","reg": "正式","ex": "I understand, but could I speak to the manager, please?","exzh": "我理解，但我能和经理谈谈吗？"},{"en": "I'm afraid this isn't acceptable.","zh": "恐怕这样是不能接受的。","reg": "正式","ex": "I'm afraid this isn't acceptable. The unit was damaged on arrival.","exzh": "恐怕这不能接受，东西到的时候就是坏的。"},{"en": "I'd like to make a complaint.","zh": "我想投诉。","reg": "正式","ex": "I'd like to make a complaint about the delivery service.","exzh": "我想投诉一下配送服务。"}]},{"id": "meetings","title": "💼 工作会议常用","note": "开会时用这些句子推进流程、插话和收尾；插话前加 Sorry to jump in 显得礼貌。","items": [{"en": "Let's get started.","zh": "我们开始吧。","reg": "中性","ex": "Okay, looks like everyone's here. Let's get started.","exzh": "好，人好像都到了，我们开始吧。"},{"en": "Can everyone hear me?","zh": "大家能听到我吗？","reg": "中性","ex": "Can everyone hear me? Okay, great.","exzh": "大家能听到我吗？好的。"},{"en": "Sorry to jump in, but...","zh": "抱歉插一句……","reg": "中性","ex": "Sorry to jump in, but I think we're missing one thing.","exzh": "抱歉插一句，我觉得我们漏了一点。"},{"en": "Just a quick update.","zh": "简单同步一下。","reg": "中性","ex": "Just a quick update. The API is done, testing starts tomorrow.","exzh": "简单同步一下，API 做完了，明天开始测试。"},{"en": "Let's circle back to that.","zh": "这个我们稍后再回来讨论。","reg": "中性","ex": "Good question. Let's circle back to that at the end.","exzh": "好问题，我们最后再回来讨论。"},{"en": "Can we take this offline?","zh": "这个会后单独聊吧？","reg": "中性","ex": "This is getting detailed. Can we take this offline?","exzh": "这越聊越细了，会后单独聊吧？"},{"en": "What are the next steps?","zh": "接下来要做什么？","reg": "中性","ex": "Okay, so what are the next steps?","exzh": "好，那接下来做什么？"},{"en": "I'll follow up on that.","zh": "这个我来跟进。","reg": "中性","ex": "I'll follow up on that and send an update tomorrow.","exzh": "这个我来跟进，明天发更新。"},{"en": "Are we on the same page?","zh": "我们想法一致吗？","reg": "中性","ex": "So we ship on Friday. Are we on the same page?","exzh": "所以周五上线，大家都清楚吧？"},{"en": "I'm blocked on this.","zh": "我这个卡住了。","reg": "随意","ex": "I'm blocked on this until the design is ready.","exzh": "设计没出来之前我这边卡住了。"},{"en": "Does anyone have any questions?","zh": "大家有什么问题吗？","reg": "中性","ex": "That's all from me. Does anyone have any questions?","exzh": "我就说这些，大家有问题吗？"},{"en": "Let's wrap it up here.","zh": "今天就到这里吧。","reg": "中性","ex": "We're out of time. Let's wrap it up here.","exzh": "时间到了，就到这里吧。"}]},{"id": "phone_calls","title": "📞 打电话常用","note": "电话里看不到表情，要多确认；信号不好时直接说 You're breaking up，母语者也常用。","items": [{"en": "Hi, this is Rui.","zh": "你好，我是 Rui。","reg": "中性","ex": "Hi, this is Rui. I'm calling about the condo.","exzh": "你好，我是 Rui，打来问一下公寓的事。"},{"en": "Is this a good time?","zh": "现在方便吗？","reg": "中性","ex": "Hey, is this a good time? It'll be quick.","exzh": "嘿，现在方便吗？很快的。"},{"en": "I'm calling about...","zh": "我打来是关于……","reg": "中性","ex": "I'm calling about my order from last week.","exzh": "我打来是问上周的订单。"},{"en": "Sorry, you're breaking up.","zh": "抱歉，你那边信号断断续续的。","reg": "随意","ex": "Sorry, you're breaking up. Can you hear me now?","exzh": "抱歉，你断断续续的，现在能听到我吗？"},{"en": "Can you hear me okay?","zh": "你能听清我说话吗？","reg": "中性","ex": "Can you hear me okay? I'm on the LRT.","exzh": "你听得清吗？我在 LRT 上。"},{"en": "Hang on a sec.","zh": "稍等一下。","reg": "随意","ex": "Hang on a sec, let me grab a pen.","exzh": "稍等，我拿支笔。"},{"en": "Could I speak to...?","zh": "我能找一下……吗？","reg": "中性","ex": "Hi, could I speak to Mr. Lim, please?","exzh": "你好，请问林先生在吗？"},{"en": "Can I call you back?","zh": "我等下回你电话可以吗？","reg": "随意","ex": "I'm driving right now. Can I call you back?","exzh": "我在开车，等下回你行吗？"},{"en": "Let me put you on speaker.","zh": "我开一下免提。","reg": "随意","ex": "Let me put you on speaker. Sarah's here too.","exzh": "我开免提，Sarah 也在。"},{"en": "Sorry, I missed your call.","zh": "抱歉错过了你的电话。","reg": "中性","ex": "Sorry, I missed your call. What's up?","exzh": "抱歉没接到你电话，什么事？"},{"en": "Could I leave a message?","zh": "我能留个言吗？","reg": "正式","ex": "He's not in? Could I leave a message?","exzh": "他不在吗？我能留个言吗？"},{"en": "Thanks for calling. Have a great day.","zh": "感谢来电，祝您愉快。","reg": "正式","ex": "Your booking is confirmed. Thanks for calling. Have a great day.","exzh": "预订已确认，感谢来电，祝您愉快。"}]},{"id": "uncertainty","title": "🤔 表达不确定和猜测","note": "不确定时别硬说 Yes/No，用 I guess / probably / I'd say 给个模糊答案，母语者天天这么说。","items": [{"en": "I'm not sure.","zh": "我不确定。","reg": "中性","ex": "A: Is the mall open today? / B: I'm not sure. Let me check.","exzh": "A：商场今天开吗？/ B：不确定，我查一下。"},{"en": "I guess so.","zh": "我想是吧。","reg": "随意","ex": "A: Is it going to rain? / B: I guess so. It looks pretty dark.","exzh": "A：会下雨吗？/ B：应该会，天挺黑的。"},{"en": "Probably.","zh": "大概吧。","reg": "随意","ex": "A: Will you be at the party? / B: Probably.","exzh": "A：你会去派对吗？/ B：大概会。"},{"en": "Maybe, I don't know.","zh": "也许吧，我也不知道。","reg": "随意","ex": "A: Do you think he'll come? / B: Maybe, I don't know.","exzh": "A：你觉得他会来吗？/ B：也许吧，不知道。"},{"en": "I'd say...","zh": "我估计……","reg": "随意","ex": "A: How long will it take? / B: I'd say about two hours.","exzh": "A：要多久？/ B：估计两个小时左右。"},{"en": "It depends.","zh": "看情况。","reg": "中性","ex": "A: How much is a Grab to KLCC? / B: It depends on the traffic.","exzh": "A：Grab 到 KLCC 多少钱？/ B：看交通情况。"},{"en": "I think so, but don't quote me on that.","zh": "我觉得是，但别当真。","reg": "随意","ex": "It closes at ten, I think, but don't quote me on that.","exzh": "我记得十点关门，但别全信我。"},{"en": "Off the top of my head,...","zh": "我一下子能想到的是……","reg": "随意","ex": "Off the top of my head, it's around RM 50.","exzh": "我大概记得是 50 令吉左右。"},{"en": "No idea.","zh": "完全不知道。","reg": "随意","ex": "A: Where's the remote? / B: No idea.","exzh": "A：遥控器在哪？/ B：完全不知道。"},{"en": "It might be...","zh": "可能是……","reg": "中性","ex": "It might be a network issue. Try again later.","exzh": "可能是网络问题，晚点再试。"},{"en": "I could be wrong, but...","zh": "我可能说错，但……","reg": "中性","ex": "I could be wrong, but I think the meeting moved to three.","exzh": "我可能记错，但会好像改到三点了。"},{"en": "I'm not entirely certain, but I believe...","zh": "我不完全确定，但我认为……","reg": "正式","ex": "I'm not entirely certain, but I believe the contract ends in June.","exzh": "我不完全确定，但合同应该六月到期。"}]}],"pron": {"pairs": [{"id": "i-long-short","title": "/iː/ vs /ɪ/ 长短 i","a": "/iː/","b": "/ɪ/","how": "/iː/ 嘴角向两边拉开像微笑，舌头抬高、肌肉绷紧，声音拉长。/ɪ/ 嘴巴放松微张，舌头稍低，短促一点，更接近“一”和“诶”之间，不是短一点的“衣”。","words": [["sheep","ship"],["leave","live"],["seat","sit"],["feel","fill"],["heat","hit"],["eat","it"],["sleep","slip"],["cheap","chip"]],"sent": [["Can you see the sheep over there?","Can you see the ship over there?"],["I want to leave here.","I want to live here."]]},{"id": "ae-e","title": "/æ/ vs /e/ 大嘴 a 和 e","a": "/æ/","b": "/e/","how": "/æ/ 嘴巴张大、下巴往下掉，嘴角往两边扯，介于“啊”和“诶”之间。/e/（美式也写 /ɛ/）嘴巴只半张，像“诶”但不滑向 i，下巴不要掉下来。","words": [["bad","bed"],["man","men"],["sad","said"],["pan","pen"],["bat","bet"],["had","head"],["sat","set"],["flash","flesh"]],"sent": [["I need a new pan.","I need a new pen."],["Where's the man?","Where are the men?"]]},{"id": "uh-ah","title": "/ʌ/ vs /ɑː/ 短促的“呃”和张大的“啊”","a": "/ʌ/","b": "/ɑː/","how": "/ʌ/ 嘴巴半张、放松，短促地发出像“呃/阿”之间的音，下巴不怎么动。/ɑː/（美式常写 /ɑ/）嘴巴张到最大、舌头压低往后，像看医生时说“啊”。","words": [["cut","cot"],["cup","cop"],["luck","lock"],["duck","dock"],["shut","shot"],["nut","not"],["rub","rob"],["bucks","box"]],"sent": [["Did you see the duck?","Did you see the dock?"],["I need some luck.","I need a lock."]]},{"id": "u-short-long","title": "/ʊ/ vs /uː/ 短 u 和长 u","a": "/ʊ/","b": "/uː/","how": "/ʊ/ 嘴唇只轻轻收圆、放松，短促，有点像“呃”和“乌”之间。/uː/ 嘴唇用力收圆往前噘，舌根抬高，声音拉长，像拉长的“乌”。","words": [["full","fool"],["pull","pool"],["look","Luke"],["would","wooed"],["hood","who'd"],["stood","stewed"],["soot","suit"],["could","cooed"]],"sent": [["I'm so full right now.","I feel like a fool right now."],["Let's pull it out.","Let's go to the pool."]]},{"id": "l-r","title": "/l/ vs /r/ 舌尖碰不碰","a": "/l/","b": "/r/","how": "/l/ 舌尖顶住上门牙后面的牙龈，气流从舌头两边出来。/r/ 舌尖不碰任何地方，往后卷或整个舌头往后缩，嘴唇微微噘圆，像“若”的开头但不摩擦。","words": [["light","right"],["long","wrong"],["lead","read"],["lock","rock"],["glass","grass"],["fly","fry"],["play","pray"],["collect","correct"]],"sent": [["That's the long way.","That's the wrong way."],["I need to collect it.","I need to correct it."]]},{"id": "l-n","title": "/l/ vs /n/ 鼻音和边音","a": "/l/","b": "/n/","how": "/l/ 舌尖顶上牙龈，气流从舌头两侧的嘴里出来，鼻子不出气。/n/ 舌尖同样位置，但气流全部从鼻子出来，捏住鼻子就发不出来；南方口音容易把两者混掉。","words": [["light","night"],["low","no"],["line","nine"],["lot","not"],["lap","nap"],["lock","knock"],["lead","need"],["lame","name"]],"sent": [["Is it light outside?","Is it night outside?"],["Did you lock the door?","Did you knock on the door?"]]},{"id": "v-w","title": "/v/ vs /w/ 咬唇和圆唇","a": "/v/","b": "/w/","how": "/v/ 上门牙轻轻咬住下嘴唇，声带振动，能感到嘴唇发麻。/w/ 牙齿不碰嘴唇，双唇先收圆噘起再迅速张开，像快速的“乌”滑到后面的元音。","words": [["vest","west"],["vine","wine"],["vet","wet"],["vow","wow"],["vent","went"],["verse","worse"],["veil","whale"],["viper","wiper"]],"sent": [["It's a nice vine.","It's a nice wine."],["I made a vow.","I said wow."]]},{"id": "th-s","title": "/θ/ vs /s/ 咬舌和不咬舌","a": "/θ/","b": "/s/","how": "/θ/ 舌尖轻轻伸到上下门牙之间，往外送气，声带不振动，不要发成“斯”。/s/ 舌尖在牙齿后面、靠近牙龈，气流从窄缝挤出来，发出“嘶”声。","words": [["think","sink"],["thick","sick"],["thank","sank"],["path","pass"],["mouth","mouse"],["worth","worse"],["faith","face"],["thumb","some"]],"sent": [["Is it worth it?","Is it worse?"],["I think it's fine.","The sink is fine."]]},{"id": "dh-d","title": "/ð/ vs /d/ 咬舌浊音和 d","a": "/ð/","b": "/d/","how": "/ð/ 舌尖放在上下门牙之间，声带振动，气流持续摩擦出来，能拉长。/d/ 舌尖顶住上牙龈，憋住再突然放开，是一下爆破，不能拉长。","words": [["they","day"],["then","den"],["though","dough"],["those","doze"],["there","dare"],["breathe","breed"],["lather","ladder"],["other","udder"]],"sent": [["They were late again.","The day was long again."],["Put it over there.","Don't you dare."]]},{"id": "sh-s","title": "/ʃ/ vs /s/ 噘嘴“嘘”和扁嘴“嘶”","a": "/ʃ/","b": "/s/","how": "/ʃ/ 嘴唇往前噘圆，舌头整体往后、抬高，发出像“嘘”的声音。/s/ 嘴角往两边扁，舌尖靠近上门牙后面，发出尖细的“嘶”。","words": [["she","see"],["ship","sip"],["shoe","Sue"],["shell","sell"],["sheet","seat"],["shave","save"],["shine","sign"],["shock","sock"]],"sent": [["I need to shave.","I need to save."],["Can I have a sheet?","Can I have a seat?"]]},{"id": "n-ng","title": "词尾 /n/ vs /ŋ/ 前鼻音和后鼻音","a": "/n/","b": "/ŋ/","how": "词尾 /n/ 结束时舌尖顶住上牙龈，像“安”的收尾。/ŋ/ 舌尖放下、舌根抬起贴住软腭，像“昂”的收尾，最后不要加出 g 的音。","words": [["thin","thing"],["ran","rang"],["win","wing"],["sin","sing"],["ban","bang"],["sun","sung"],["kin","king"],["run","rung"]],"sent": [["I ran twice.","It rang twice."],["We can win.","We can sing."]]},{"id": "final-consonant","title": "词尾辅音有无 不要吞掉尾音","a": "无尾辅音","b": "有尾辅音","how": "中文音节多以元音结尾，说英语时容易把词尾的 t、d、k 吞掉，结果 road 听起来像 row。尾辅音可以不爆破，但舌头要做到位、短暂停顿一下，前面的元音也会因此变短。","words": [["row","road"],["see","seat"],["go","goat"],["tie","tight"],["pay","paid"],["why","white"],["buy","bike"],["know","note"]],"sent": [["I'll pay you later.","I paid you yesterday."],["Did you buy it?","Did you bike there?"]]}],"connected": [{"type": "缩略","en": "I'm going to call you later.","sounds": "/aɪm ˈɡʌnə kɑːl jə ˈleɪɾɚ/ 'I'm gonna'","zh": "going to 表示“将要”时口语几乎都说成 gonna；但“去某地”的 going to the mall 不能缩。"},{"type": "缩略","en": "I want to go home.","sounds": "/aɪ ˈwɑːnə ɡoʊ hoʊm/ 'wanna'","zh": "want to 连在一起变成 wanna，t 和 t 合并后几乎消失。"},{"type": "缩略","en": "I've got to go.","sounds": "/aɪv ˈɡɑːɾə ɡoʊ/ 'I gotta go'","zh": "got to 变成 gotta，t 变成美式闪音，像轻轻的 d；I've 常常也被吞掉。"},{"type": "缩略","en": "Let me see.","sounds": "/ˈlemi siː/ 'lemme see'","zh": "let me 的 t 被吞掉，me 弱读，听起来像一个词 lemme。"},{"type": "缩略","en": "It's kind of cold in here.","sounds": "/ɪts ˈkaɪndə koʊld/ 'kinda'","zh": "kind of 弱读成 kinda，意思是“有点儿”，非常高频。"},{"type": "同化","en": "Did you eat yet?","sounds": "/ˈdɪdʒə iːt jet/ 'didja'","zh": "d 碰到 you 的 /j/ 融合成 /dʒ/，did you 听起来像 didja；说得快甚至变成 Jeet yet?"},{"type": "同化","en": "What are you doing?","sounds": "/ˈwʌtʃə ˈduːɪŋ/ 'whatcha doing'","zh": "what are you 三个词压成 whatcha，t 和 y 融合成 ch 音。"},{"type": "弱读","en": "Do you want some?","sounds": "/dʒə ˈwɑːnt səm/ 'd'you want some'","zh": "do you 弱读成 d'you /djə/，再快就变成 /dʒə/，some 也弱读成 /səm/。"},{"type": "连读","en": "I'll have an apple.","sounds": "/aɪl hæv ə ˈnæpəl/","zh": "an 的 n 连到 apple 上，听起来像 a napple。辅音结尾+元音开头的词要连起来读。"},{"type": "连读","en": "Can you pick it up?","sounds": "/ˈpɪkɪˈɾʌp/ 'pi-ki-dup'","zh": "三个词连成一串：k 连到 it，t 在两个元音之间变成闪音，像轻 d。"},{"type": "连读","en": "Turn it off, please.","sounds": "/ˈtɝːnɪˈɾɑːf/ 'tur-ni-doff'","zh": "n 连到 it，it 的 t 变闪音再连到 off，听起来像一个长词。"},{"type": "吞音","en": "I'll see you the next day.","sounds": "/neks ˈdeɪ/ 'nex day'","zh": "三个辅音 kst+d 挤在一起，中间的 t 被省略，读成 nex day。"},{"type": "缩略","en": "I have to work tomorrow.","sounds": "/aɪ ˈhæftə wɝːk/ 'I hafta'","zh": "have to 里 v 受后面 t 影响清化成 f，读成 hafta；has to 读成 hasta。"},{"type": "同化","en": "Could you help me with this?","sounds": "/ˈkʊdʒə ˈhelp mi/ 'couldja'","zh": "could 的 d 和 you 融合成 /dʒ/，听起来像 couldja。"},{"type": "同化","en": "Would you like some coffee?","sounds": "/ˈwʊdʒə laɪk səm ˈkɑːfi/ 'wouldja'","zh": "would you 同样 d+y 变成 /dʒ/，礼貌问句里极常见。"},{"type": "缩略","en": "I don't know.","sounds": "/aɪ dəˈnoʊ/ 'I dunno'","zh": "don't know 弱化成 dunno，t 消失，don't 的元音变成弱读 /ə/。"},{"type": "弱读","en": "There were a lot of people.","sounds": "/əˈlɑːɾə ˈpiːpəl/ 'a lotta'","zh": "of 弱读成 /ə/，和 lot 连起来；t 夹在元音中间变闪音，读成 a lotta。"},{"type": "弱读","en": "We're out of time.","sounds": "/wɪr ˈaʊɾə taɪm/ 'outta time'","zh": "out of 读成 outta，of 只剩一个 /ə/。"},{"type": "弱读","en": "It's sort of complicated.","sounds": "/ɪts ˈsɔːrɾə ˈkɑːmplɪkeɪɾɪd/ 'sorta'","zh": "sort of 读成 sorta，和 kind of 一样表示“有点儿”。"},{"type": "弱读","en": "How about this one?","sounds": "/haʊ əˈbaʊt ðɪs wʌn/ 'how 'bout'","zh": "about 的开头 /ə/ 经常被吞掉，说成 how 'bout。"},{"type": "连读","en": "Check it out.","sounds": "/ˈtʃekɪˈɾaʊt/ 'che-ki-dout'","zh": "k 连 it，t 变闪音连 out，像一个词 chekidout。"},{"type": "连读","en": "Get up, it's already eight.","sounds": "/ɡeˈɾʌp/ 'ge-dup'","zh": "get 的 t 碰到元音 up，变成闪音，读成 gedup。"},{"type": "吞音","en": "I went out last night.","sounds": "/læs ˈnaɪt/ 'las night'","zh": "last 的 t 夹在 s 和 n 之间被吞掉，只读 las night。"},{"type": "同化","en": "Don't you like it?","sounds": "/ˈdoʊntʃə laɪk ɪt/ 'dontcha'","zh": "t 和 you 的 /j/ 融合成 ch 音，don't you 读成 dontcha。"},{"type": "同化","en": "I miss you so much.","sounds": "/aɪ ˈmɪʃə soʊ mʌtʃ/ 'mish-you'","zh": "s 碰到 you 的 /j/ 变成 sh 音，miss you 听起来像 mishyou。"},{"type": "吞音","en": "Good morning!","sounds": "/ɡʊ ˈmɔːrnɪŋ/ 'goo' morning'","zh": "good 的 d 碰到 m 不爆破，几乎听不到，只做口型停顿。"},{"type": "弱读","en": "Tell them I'm on my way.","sounds": "/ˈteləm aɪm ɑːn maɪ weɪ/ 'tell 'em'","zh": "them 弱读时 th 脱落，只剩 'em /əm/，直接连到前一个词。"},{"type": "连读","en": "Not at all.","sounds": "/ˈnɑːɾəˈɾɑːl/ 'na-da-dall'","zh": "两个 t 都在元音之间变成闪音，三个词连成一串。"},{"type": "弱读","en": "What do you want to eat?","sounds": "/ˈwʌɾəjə ˈwɑːnə iːt/ 'whaddaya wanna eat'","zh": "what do you 压成 whaddaya，want to 又变成 wanna，母语者语速里很常见。"},{"type": "缩略","en": "Give me a sec.","sounds": "/ˈɡɪmi ə sek/ 'gimme a sec'","zh": "give me 的 v 被吞掉，读成 gimme；sec 是 second 的口语简称。"}],"shadow": [{"group": "日常起居","items": [{"en": "I didn't sleep well last night, so I'm pretty tired.","zh": "我昨晚没睡好，所以挺累的。"},{"en": "Can you turn off the lights when you leave?","zh": "你走的时候能把灯关了吗？"},{"en": "I usually wake up around seven on weekdays.","zh": "工作日我一般七点左右起床。"},{"en": "Have you seen my phone charger anywhere?","zh": "你有没有看到我的手机充电器？"},{"en": "I'm going to take a quick shower before dinner.","zh": "我晚饭前先去冲个澡。"},{"en": "It's freezing in here. Can you turn off the air-con?","zh": "这里冷死了，你能把空调关了吗？"},{"en": "I really need to do laundry this weekend.","zh": "我这周末真的得洗衣服了。"},{"en": "Don't forget to take out the trash tonight.","zh": "今晚别忘了倒垃圾。"},{"en": "I'll be home late, so don't wait up.","zh": "我会晚点回家，不用等我。"},{"en": "We're out of milk again. I'll grab some later.","zh": "牛奶又没了，我等下去买点。"},{"en": "My alarm didn't go off this morning.","zh": "我今天早上闹钟没响。"},{"en": "I'm going to bed early tonight.","zh": "我今晚要早点睡。"},{"en": "Did you lock the door when you came in?","zh": "你进来的时候锁门了吗？"},{"en": "The Wi-Fi in my condo keeps cutting out.","zh": "我公寓的 Wi-Fi 老是断。"},{"en": "Can you help me move this table real quick?","zh": "你能帮我搬一下这张桌子吗？"},{"en": "I've been meaning to clean my room all week.","zh": "我一整周都想着要打扫房间。"},{"en": "It's raining again, so take an umbrella.","zh": "又下雨了，带把伞吧。"},{"en": "I usually just make something simple for breakfast.","zh": "我早餐一般就随便弄点简单的。"},{"en": "The neighbors were really loud last night.","zh": "昨晚邻居特别吵。"},{"en": "Wait, I think I left the stove on.","zh": "等等，我好像没关炉子。"}]},{"group": "吃喝点餐","items": [{"en": "Can I get an iced latte, less sugar?","zh": "我要一杯冰拿铁，少糖。"},{"en": "Are you guys ready to order?","zh": "你们准备好点餐了吗？"},{"en": "I'll have the same thing as her.","zh": "我要跟她一样的。"},{"en": "Could we get the bill, please?","zh": "麻烦买单。"},{"en": "Is this spicy? I can't really handle spicy food.","zh": "这个辣吗？我不太能吃辣。"},{"en": "Let's go to the mamak for some roti canai.","zh": "我们去嘛嘛档吃印度煎饼吧。"},{"en": "Can I get this to go?","zh": "这个可以打包吗？"},{"en": "What would you recommend? It's my first time here.","zh": "你推荐什么？我第一次来。"},{"en": "I'm not that hungry, so I'll just get a drink.","zh": "我不太饿，就点杯喝的吧。"},{"en": "This is way too sweet for me.","zh": "这个对我来说太甜了。"},{"en": "Do you want to split a pizza with me?","zh": "要不要跟我分一个披萨？"},{"en": "We've been waiting for our food for half an hour.","zh": "我们的菜已经等了半个小时了。"},{"en": "Could I get some more water, please?","zh": "可以再给我一点水吗？"},{"en": "I'm trying to eat less rice these days.","zh": "我最近在尽量少吃米饭。"},{"en": "Let's just order Grab Food. I don't feel like cooking.","zh": "直接叫 Grab 外卖吧，我不想做饭。"},{"en": "Do you take Touch 'n Go here?","zh": "你们这里能用 Touch 'n Go 付款吗？"},{"en": "Sorry, I didn't order this. I ordered the chicken rice.","zh": "不好意思，我没点这个，我点的是鸡饭。"},{"en": "Can you make it without ice?","zh": "可以不加冰吗？"},{"en": "That was really good. We should come back here.","zh": "真好吃，我们以后还要再来。"},{"en": "How much is it altogether? Can I pay by card?","zh": "一共多少钱？可以刷卡吗？"}]},{"group": "出行购物","items": [{"en": "How long does it take to get to KLCC?","zh": "去 KLCC 要多久？"},{"en": "Which LRT station is closest to here?","zh": "离这里最近的 LRT 站是哪个？"},{"en": "I'll just book a Grab. It's faster.","zh": "我直接叫个 Grab 吧，比较快。"},{"en": "Traffic is crazy right now. I'll be about twenty minutes late.","zh": "现在堵得要命，我会晚到二十分钟左右。"},{"en": "Excuse me, do you have this in a smaller size?","zh": "不好意思，这个有小一号的吗？"},{"en": "Can I try this on? Where's the fitting room?","zh": "我可以试一下吗？试衣间在哪？"},{"en": "Is there a discount if I buy two?","zh": "买两个有优惠吗？"},{"en": "I'm just looking for now, thanks.","zh": "我先随便看看，谢谢。"},{"en": "Do you know where I can find the batteries?","zh": "你知道电池放在哪吗？"},{"en": "I think my Grab driver went the wrong way.","zh": "我觉得我的 Grab 司机走错路了。"},{"en": "Could you drop me off at the main entrance?","zh": "你能在正门放我下车吗？"},{"en": "I left my card at home. Can I pay with cash?","zh": "我卡忘在家了，可以付现金吗？"},{"en": "That's a little out of my budget.","zh": "这有点超出我的预算了。"},{"en": "Is it cheaper if I buy it online?","zh": "网上买会便宜一点吗？"},{"en": "I missed my train, so I'll take the next one.","zh": "我错过了这班车，坐下一班吧。"},{"en": "Can I return this if it doesn't fit?","zh": "如果不合身可以退吗？"},{"en": "Is there an ATM anywhere around here?","zh": "这附近有没有提款机？"},{"en": "The parking here is so expensive.","zh": "这里停车好贵。"},{"en": "Do you deliver, or do I have to pick it up?","zh": "你们送货吗，还是我得自己来拿？"},{"en": "I've been looking for this everywhere.","zh": "我到处都在找这个。"}]},{"group": "工作沟通","items": [{"en": "Can we push the meeting to three o'clock?","zh": "会议能推到三点吗？"},{"en": "I'll send you the details after lunch.","zh": "我午饭后把细节发给你。"},{"en": "Sorry, I'm running a few minutes late.","zh": "不好意思，我会晚几分钟。"},{"en": "Could you walk me through how this works?","zh": "你能给我讲一下这个怎么用吗？"},{"en": "I'm still working on it. It should be done by Friday.","zh": "我还在做，周五前应该能完成。"},{"en": "Let me double-check and get back to you.","zh": "我再确认一下，然后回复你。"},{"en": "I didn't quite catch that. Could you say it again?","zh": "我没太听清，你能再说一遍吗？"},{"en": "I think there's a bug on the login page.","zh": "我觉得登录页有个 bug。"},{"en": "Can you share your screen for a sec?","zh": "你能共享一下屏幕吗？"},{"en": "That makes sense. Let's go with your idea.","zh": "有道理，就按你的想法来。"},{"en": "I'm not sure that's going to work.","zh": "我不确定这样行得通。"},{"en": "Who's in charge of this project?","zh": "这个项目谁负责？"},{"en": "I've already fixed it and pushed the changes.","zh": "我已经修好了，代码也推上去了。"},{"en": "Can we jump on a quick call?","zh": "我们能快速打个电话吗？"},{"en": "Just to be clear, the deadline is next Monday, right?","zh": "确认一下，截止日期是下周一，对吧？"},{"en": "I'll be working from home tomorrow.","zh": "我明天在家办公。"},{"en": "Sorry, I missed your message. I was in a meeting.","zh": "抱歉没看到你的消息，我刚在开会。"},{"en": "Do you have a few minutes to talk?","zh": "你有几分钟可以聊一下吗？"},{"en": "It works on my machine, but not on the server.","zh": "在我电脑上能跑，但在服务器上不行。"},{"en": "Let's take this offline and talk about it later.","zh": "这个我们会后再单独聊吧。"}]},{"group": "社交闲聊","items": [{"en": "Hey, long time no see! How have you been?","zh": "嘿，好久不见！最近怎么样？"},{"en": "What do you usually do for fun on weekends?","zh": "你周末一般做什么消遣？"},{"en": "How long have you been living in KL?","zh": "你在吉隆坡住多久了？"},{"en": "So where are you from originally?","zh": "那你老家是哪里的？"},{"en": "I've been super busy with work lately.","zh": "我最近工作超级忙。"},{"en": "Do you want to grab a coffee sometime?","zh": "找时间一起喝杯咖啡吧？"},{"en": "Have you watched anything good recently?","zh": "你最近有看什么好看的吗？"},{"en": "I'm not really a morning person.","zh": "我不太是早起型的人。"},{"en": "We should hang out more often.","zh": "我们应该多出来聚聚。"},{"en": "What are you up to this weekend?","zh": "你这周末打算干嘛？"},{"en": "I went hiking last weekend. It was amazing.","zh": "我上周末去爬山了，超棒的。"},{"en": "That sounds like a lot of fun.","zh": "听起来很好玩。"},{"en": "Sorry, I can't make it tonight. Maybe next time?","zh": "抱歉今晚去不了，下次吧？"},{"en": "So how did you two meet?","zh": "那你们俩是怎么认识的？"},{"en": "I've never been there, but I'd love to go.","zh": "我从没去过，但很想去。"},{"en": "Are you going to Jason's birthday party on Saturday?","zh": "你周六去 Jason 的生日派对吗？"},{"en": "It was nice meeting you. Let's keep in touch.","zh": "很高兴认识你，保持联系。"},{"en": "What kind of music are you into?","zh": "你喜欢什么类型的音乐？"},{"en": "I don't think I've seen you around here before.","zh": "我好像之前没在这见过你。"},{"en": "Text me when you get home, okay?","zh": "到家了给我发个消息，好吗？"}]},{"group": "情绪和看法","items": [{"en": "I'm so stressed out about this deadline.","zh": "这个截止日期让我压力好大。"},{"en": "Honestly, I don't think it's worth the money.","zh": "说实话，我觉得不值这个钱。"},{"en": "That's exactly what I was thinking.","zh": "我也正是这么想的。"},{"en": "I'm really happy for you. You deserve it.","zh": "真为你高兴，这是你应得的。"},{"en": "I'm kind of worried about the interview tomorrow.","zh": "我有点担心明天的面试。"},{"en": "It's not a big deal. Don't worry about it.","zh": "没什么大不了的，别担心。"},{"en": "I can't believe he actually said that.","zh": "真不敢相信他居然说了那种话。"},{"en": "To be honest, I'm a little disappointed.","zh": "说实话，我有点失望。"},{"en": "I see your point, but I don't totally agree.","zh": "我明白你的意思，但我不完全同意。"},{"en": "That was the best movie I've seen all year.","zh": "那是我今年看过最好看的电影。"},{"en": "I'm so tired of dealing with this.","zh": "我真的受够了处理这件事。"},{"en": "It's actually way better than I expected.","zh": "其实比我预想的好太多了。"},{"en": "Sometimes I feel like nobody listens to me.","zh": "有时候我觉得没人听我说话。"},{"en": "Wow, that's really impressive. How did you do that?","zh": "哇，太厉害了，你是怎么做到的？"},{"en": "I'm not a big fan of crowded places.","zh": "我不太喜欢人多的地方。"},{"en": "I was so nervous that I couldn't sleep.","zh": "我紧张到睡不着。"},{"en": "If I were you, I'd just ask him directly.","zh": "如果我是你，我就直接问他。"},{"en": "It's so annoying when people are always late.","zh": "别人老是迟到真的很烦。"},{"en": "I'm actually really looking forward to it.","zh": "其实我挺期待的。"},{"en": "Don't worry, I think it'll work out in the end.","zh": "别担心，我觉得最后会好起来的。"}]}]},"topics": [{"id": "morning_routine","cat": "日常","level": "基础","q": "Can you walk me through your typical morning routine?","qzh": "能说说你平时早上的日常安排吗？","points": ["What time you usually wake up","The first few things you do","What you have for breakfast","How weekday and weekend mornings differ"],"phrases": [["the first thing I do is…","我做的第一件事是……"],["hit the snooze button","按下闹钟的贪睡键"],["grab a quick breakfast","随便吃点早餐"],["get ready for work","准备去上班"],["on a good day","状态好的时候"],["it really sets the tone for the day","它真的决定了一整天的状态"]],"sample": "So, I usually wake up around seven, though honestly I hit the snooze button at least once. The first thing I do is drink a glass of water, and then, yeah, I check my phone, which I know is a bad habit. After that I take a quick shower and grab breakfast, usually toast and a coffee, or sometimes roti canai if I go downstairs. On a good day I try to do ten minutes of stretching, because sitting at a desk all day kills my back. Weekends are totally different, though. I sleep in until nine or so and take my time. I think a calm morning really sets the tone for the day.","samplezh": "嗯，我一般七点左右起床，不过说实话，我至少会按一次贪睡键。我做的第一件事是喝一杯水，然后，对，我会看手机，我知道这是个坏习惯。之后我快速冲个澡，吃点早餐，通常是吐司配咖啡，有时候下楼吃个印度煎饼。状态好的时候，我会拉伸十分钟，因为整天坐在桌前，背真的受不了。不过周末就完全不一样了，我会睡到九点左右，慢慢来。我觉得一个平静的早晨真的决定了一整天的状态。"},{"id": "weekend_plans","cat": "日常","level": "基础","q": "What do you usually do on weekends?","qzh": "你周末通常做什么？","points": ["How you relax after the work week","Chores or errands you need to do","Activities with friends or family","Your ideal weekend"],"phrases": [["sleep in","睡懒觉"],["run errands","办杂事、跑腿"],["catch up with friends","和朋友叙叙旧"],["chill at home","在家放松"],["it depends on the week","要看那周的情况"],["recharge my batteries","给自己充充电"]],"sample": "Well, it kind of depends on the week. If work was super busy, I just want to chill at home, sleep in, and maybe binge a show. Saturday mornings are usually for errands, like grocery shopping or doing laundry, the boring stuff. Then in the afternoon or evening I try to catch up with friends. We'll go to a mall, or just sit at a mamak and talk for hours. Sundays are slower. I like to cook something simple and plan the next week. My ideal weekend, though, would be a short trip out of the city, like to a beach or the hills. That's how I really recharge my batteries.","samplezh": "嗯，这要看那一周的情况。如果工作特别忙，我就只想在家放松、睡懒觉，可能再一口气追个剧。周六上午一般用来办杂事，比如去超市买菜、洗衣服，都是些无聊的事。到了下午或晚上，我会尽量和朋友聚一聚。我们会去商场逛逛，或者就坐在嘛嘛档聊好几个小时。周日节奏更慢。我喜欢做点简单的饭，规划一下下周。不过我理想的周末是出城短途旅行，比如去海边或者山上。那才是我真正给自己充电的方式。"},{"id": "favorite_food","cat": "日常","level": "基础","q": "What's your favorite food, and why do you like it?","qzh": "你最喜欢的食物是什么？为什么喜欢？","points": ["Name the dish and describe it","How it tastes and how it's made","When or where you usually eat it","Any memories connected to it"],"phrases": [["I'm a big fan of…","我超爱……"],["it's packed with flavor","味道特别浓郁"],["comfort food","安慰食物、让人舒心的食物"],["it reminds me of home","它让我想起家"],["I could eat it every day","我可以天天吃"],["hits the spot","正合心意、特别满足"]],"sample": "Honestly, my favorite food has to be hot pot. It's not just one dish, right? It's more like an experience. You have a big pot of boiling soup in the middle, and everyone cooks their own meat, veggies, tofu, whatever they like. I'm a big fan of the spicy broth, it's packed with flavor. I usually have it with friends, especially on a rainy evening, because it just hits the spot. I think the reason I love it so much is that it reminds me of home. When I was a kid, my family always had hot pot during holidays. So for me it's real comfort food, not just something tasty.","samplezh": "说实话，我最喜欢的食物一定是火锅。它不只是一道菜，对吧？更像是一种体验。中间一大锅滚烫的汤，每个人自己煮肉、蔬菜、豆腐，想吃什么煮什么。我超爱麻辣锅底，味道特别浓郁。我一般和朋友一起吃，尤其是下雨的晚上，特别满足。我觉得我这么爱它，是因为它让我想起家。小时候，我们家过节总是吃火锅。所以对我来说，它是真正让人舒心的食物，不只是好吃而已。"},{"id": "hometown","cat": "日常","level": "基础","q": "Tell me about your hometown.","qzh": "说说你的家乡吧。","points": ["Where it is and how big it is","What it's famous for","What you like or dislike about it","How it has changed"],"phrases": [["I grew up in…","我在……长大"],["it's known for…","它以……出名"],["a mid-sized city","一座中等规模的城市"],["the pace of life","生活节奏"],["it's changed a lot","它变化很大"],["I miss it sometimes","我有时候会想念它"]],"sample": "So I grew up in a mid-sized city in China. It's not super famous internationally, but it's known for its food, especially noodles, and there are some nice mountains nearby. What I like about it is the pace of life. It's way more relaxed than big cities like Shanghai, and people are pretty friendly. On the downside, there weren't many tech jobs, which is one reason I left. It's changed a lot in the last ten years, though. There's a new subway, lots of shopping malls, and the old streets I used to walk around are mostly gone. I miss it sometimes, especially the food and my family.","samplezh": "我是在中国一座中等规模的城市长大的。它在国际上不是很出名，但以美食出名，尤其是面，附近还有一些很漂亮的山。我喜欢它的生活节奏，比上海那样的大城市轻松多了，人也挺友善的。缺点是，那里科技类的工作不多，这也是我离开的原因之一。不过过去十年它变化很大，有了新地铁，很多购物中心，我以前常逛的老街基本都没了。我有时候会想念它，尤其是那里的食物和家人。"},{"id": "sleep_habits","cat": "日常","level": "基础","q": "Do you get enough sleep? Describe your sleep habits.","qzh": "你睡得够吗？说说你的睡眠习惯。","points": ["What time you go to bed and wake up","Whether you sleep well","What keeps you up at night","What you do to sleep better"],"phrases": [["I'm a night owl","我是个夜猫子"],["stay up late","熬夜"],["toss and turn","辗转反侧"],["doomscrolling","停不下来地刷手机"],["I'm trying to cut back on…","我在努力减少……"],["wake up feeling refreshed","醒来神清气爽"]],"sample": "To be honest, no, I don't think I get enough sleep. I'm kind of a night owl. I usually go to bed around one, and then I have to get up at seven for work, so that's only like six hours. The main problem is my phone. I tell myself I'll just check one thing, and then suddenly it's been an hour of doomscrolling. Sometimes I also toss and turn because I'm still thinking about a bug from work. Lately I'm trying to cut back on screen time before bed, and I stopped drinking coffee after three p.m. It's helping a little. On the days I sleep seven hours, I really wake up feeling refreshed.","samplezh": "说实话，我觉得我睡得不够。我有点夜猫子，通常一点左右睡，然后七点就得起床上班，所以才六个小时左右。主要问题是手机。我跟自己说就看一下，结果一不小心刷了一个小时。有时候我还会辗转反侧，因为脑子里还在想工作上的bug。最近我在努力减少睡前看屏幕的时间，下午三点后也不喝咖啡了。有一点帮助。睡够七个小时的那几天，我醒来真的神清气爽。"},{"id": "shopping_habits","cat": "日常","level": "基础","q": "Do you prefer shopping online or in stores?","qzh": "你更喜欢网购还是去实体店购物？","points": ["What you usually buy online","What you prefer to buy in person","Pros and cons of each","Any impulse buying habits"],"phrases": [["it's way more convenient","方便太多了"],["compare prices","比价"],["try it on","试穿"],["impulse buy","冲动消费"],["free shipping","包邮"],["I end up buying…","我最后还是买了……"]],"sample": "Mostly online, to be honest. It's just way more convenient. I use Shopee and Lazada for almost everything, like phone cables, household stuff, even snacks. I can compare prices in a few seconds, and there's often free shipping. But for clothes and shoes, I prefer going to a store, because I want to try them on first. I've bought shirts online that looked great in the photo and then, yeah, totally didn't fit. Groceries I usually buy in person too, because I like picking my own fruit. The one downside of online shopping is impulse buying. I open the app to buy one thing, and I end up buying five.","samplezh": "说实话，大部分是网购，方便太多了。我几乎什么都在Shopee和Lazada上买，比如手机线、日用品，甚至零食。几秒钟就能比价，还经常包邮。但衣服和鞋子我更喜欢去实体店买，因为想先试穿。我在网上买过照片里看着很好看的衬衫，结果，嗯，完全不合身。买菜我一般也去店里，因为我喜欢自己挑水果。网购唯一的缺点是冲动消费。我打开App想买一样东西，最后买了五样。"},{"id": "phone_use","cat": "日常","level": "进阶","q": "How much time do you spend on your phone, and what do you use it for?","qzh": "你每天花多少时间在手机上？主要用来做什么？","points": ["Your daily screen time","The apps you use most","Whether it's useful or a distraction","Any attempts to use it less"],"phrases": [["my screen time is embarrassing","我的屏幕使用时间很丢人"],["mindlessly scroll","无意识地刷"],["I can't live without…","我离不开……"],["it's a double-edged sword","它是一把双刃剑"],["set a limit","设置限制"],["out of habit","出于习惯"]],"sample": "Oh, my screen time is kind of embarrassing, around five or six hours a day. A lot of that is actually useful, though. I use WhatsApp for work and family, Grab for rides and food, and I watch YouTube to learn English and tech stuff. Those I honestly can't live without. The problem is the time I spend mindlessly scrolling, like short videos or Xiaohongshu. I don't even enjoy it that much, I just do it out of habit. So for me the phone is definitely a double-edged sword. Recently I set a limit of one hour for social media apps, and I leave my phone in another room when I'm working. It's not perfect, but it's better.","samplezh": "哦，我的屏幕使用时间有点丢人，一天大概五到六个小时。不过其中很多其实是有用的。我用WhatsApp联系工作和家人，用Grab打车点外卖，还看YouTube学英语和技术。这些我真的离不开。问题在于无意识刷手机的时间，比如短视频或者小红书。我其实也没那么喜欢，只是出于习惯。所以对我来说手机绝对是一把双刃剑。最近我给社交媒体App设了一小时的限制，工作的时候把手机放到另一个房间。不完美，但好多了。"},{"id": "weather","cat": "日常","level": "基础","q": "What's the weather like where you live? Do you like it?","qzh": "你住的地方天气怎么样？你喜欢吗？","points": ["Describe the typical weather","How it affects your daily life","Your favorite kind of weather","Compare it with your hometown"],"phrases": [["it's hot and humid all year round","一年四季又热又潮"],["it pours","下倾盆大雨"],["out of nowhere","突然、毫无预兆"],["I'm sweating like crazy","我汗流不止"],["I've gotten used to it","我已经习惯了"],["I'm not a fan of…","我不太喜欢……"]],"sample": "Well, in KL it's basically hot and humid all year round. There's no real winter, which was a big change for me. Almost every afternoon, it suddenly pours out of nowhere, like a crazy thunderstorm, and then an hour later it's sunny again. So I always carry an umbrella. The heat definitely affects my daily life. If I walk ten minutes outside, I'm sweating like crazy, so I take Grab a lot, and I basically live in air-conditioned places. Honestly, I'm not a fan of the humidity, but I've gotten used to it. My favorite weather is actually cool and dry, like autumn back home. I really miss wearing a jacket sometimes.","samplezh": "嗯，吉隆坡基本上一年四季都又热又潮，没有真正的冬天，这对我来说是个很大的变化。几乎每天下午都会突然下起倾盆大雨，像疯狂的雷暴，然后一个小时后又出太阳了。所以我总是带着伞。炎热确实影响我的日常生活。在外面走十分钟就汗流不止，所以我经常打Grab，基本上住在有空调的地方。说实话，我不太喜欢这种潮湿，但已经习惯了。我最喜欢的天气其实是凉爽干燥的，像老家的秋天。有时候我真的很怀念穿外套的感觉。"},{"id": "your_job","cat": "工作","level": "基础","q": "What do you do for work? Describe a typical day.","qzh": "你是做什么工作的？描述一下你典型的一天。","points": ["Your role and what your company does","Your main responsibilities","What a normal workday looks like","What you like about the job"],"phrases": [["I work as a…","我的工作是……"],["I'm mainly responsible for…","我主要负责……"],["we have a stand-up every morning","我们每天早上开站会"],["most of my day is spent…","我一天大部分时间在……"],["it can be stressful, but…","可能会有压力，但……"],["the best part is…","最好的部分是……"]],"sample": "So I work as a software developer at a tech company here in KL. We build a web platform for online businesses, and I'm mainly responsible for the backend, like APIs and the database. A typical day starts with a stand-up meeting at ten, where everyone shares what they're working on and if they're blocked. After that, most of my day is spent coding, reviewing pull requests, and, honestly, fixing bugs. Sometimes I have meetings with the product team to clarify requirements. It can be stressful, especially before a release, but I like it overall. The best part is when I solve a tricky problem and see real users using the feature.","samplezh": "我在吉隆坡一家科技公司做软件开发。我们为线上商家开发一个网页平台，我主要负责后端，比如API和数据库。典型的一天从十点的站会开始，大家分享自己在做什么、有没有被卡住。之后我一天大部分时间都在写代码、审查合并请求，说实话，还有修bug。有时候我会和产品团队开会，确认需求。可能会有压力，尤其是发布之前，但总体上我挺喜欢的。最好的部分是解决了一个棘手的问题，并看到真实用户在用这个功能。"},{"id": "proud_project","cat": "工作","level": "进阶","q": "Describe a project you're proud of.","qzh": "描述一个你引以为傲的项目。","points": ["What the project was and why it mattered","Your role in it","A challenge you faced","The result and what you learned"],"phrases": [["I was in charge of…","我负责……"],["the goal was to…","目标是……"],["we ran into a problem","我们遇到了一个问题"],["it turned out that…","结果发现……"],["in the end","最后"],["it was a huge learning experience","这是一次很大的学习经历"]],"sample": "One project I'm really proud of is when we rebuilt our search feature last year. The old one was super slow, like five seconds per search, and users were complaining all the time. I was in charge of the backend part. The goal was to get it under half a second. We ran into a problem early on, because the database queries just couldn't scale. It turned out we needed a proper search engine, so I learned Elasticsearch pretty much from scratch. It was stressful, but in the end we got the response time down to about two hundred milliseconds. My manager actually mentioned it in the company meeting. It was a huge learning experience for me.","samplezh": "我特别自豪的一个项目是去年我们重做搜索功能。旧的搜索特别慢，一次要五秒左右，用户一直在抱怨。我负责后端部分。目标是把它降到半秒以内。我们一开始就遇到了问题，因为数据库查询根本扩展不了。结果发现我们需要一个真正的搜索引擎，所以我基本上从零开始学了Elasticsearch。压力很大，但最后我们把响应时间降到了两百毫秒左右。我经理还在公司大会上提到了这件事。对我来说这是一次很大的学习经历。"},{"id": "working_from_home","cat": "工作","level": "基础","q": "Do you work from home? What's it like?","qzh": "你在家办公吗？感觉怎么样？","points": ["How often you work from home","What your home setup looks like","The advantages","The challenges and how you deal with them"],"phrases": [["I work from home twice a week","我每周在家办公两天"],["skip the commute","省掉通勤"],["it's easy to get distracted","很容易分心"],["the line between work and life gets blurry","工作和生活的界限变得模糊"],["I make a point of…","我刻意坚持……"],["it works for me","这对我很合适"]],"sample": "Yeah, I work from home about two or three days a week. My setup is pretty simple, just a desk in my condo, a second monitor, and a decent chair, which I think is the most important thing. The biggest advantage is that I skip the commute. Traffic in KL can be crazy, so that saves me like an hour a day. I also focus better without people tapping me on the shoulder. But it's easy to get distracted at home, and sometimes the line between work and life gets blurry. I end up checking Slack at ten p.m. So now I make a point of shutting my laptop at seven. Overall, it works for me.","samplezh": "对，我每周在家办公两三天。我的设备很简单，就是公寓里一张桌子、一个副屏，还有一把不错的椅子，我觉得椅子最重要。最大的好处是省掉了通勤。吉隆坡的交通可能很疯狂，这样每天能省一个小时左右。没有人拍我肩膀，我也更专注。但在家很容易分心，而且有时候工作和生活的界限会变得模糊，我会晚上十点还在看Slack。所以现在我刻意坚持七点就合上电脑。总的来说，这对我很合适。"},{"id": "difficult_bug","cat": "工作","level": "进阶","q": "Tell me about a difficult bug or problem you had to solve.","qzh": "说说你遇到过的一个很难的bug或问题。","points": ["What the problem was and how you found it","Why it was hard to fix","How you finally solved it","What you'd do differently next time"],"phrases": [["it only happened in production","只在生产环境出现"],["I couldn't reproduce it","我复现不了"],["I spent hours digging into…","我花了好几个小时深挖……"],["the root cause was…","根本原因是……"],["it was such a relief","真是松了一口气"],["lesson learned","吸取了教训"]],"sample": "Oh, I remember one really annoying bug. Some users were getting charged twice, but only sometimes, and it only happened in production. I couldn't reproduce it on my machine at all, which drove me crazy. I spent hours digging into the logs, and finally I noticed the duplicate requests came in within like fifty milliseconds of each other. It turned out the root cause was a race condition. When the network was slow, the app retried the payment request, and our backend didn't check if it was already processed. So I added an idempotency key to every request. When it finally worked, it was such a relief. Lesson learned: always design for retries.","samplezh": "哦，我记得一个特别烦人的bug。有些用户被扣了两次钱，但只是偶尔，而且只在生产环境出现。我在自己电脑上完全复现不了，快把我逼疯了。我花了好几个小时深挖日志，最后发现那些重复请求相隔只有五十毫秒左右。结果发现根本原因是竞态条件。网络慢的时候，应用会重试支付请求，而我们后端没有检查这个请求是否已经处理过。所以我给每个请求加了幂等键。终于搞定的时候，真是松了一口气。吸取的教训是：设计时一定要考虑重试。"},{"id": "learning_new_tech","cat": "工作","level": "进阶","q": "How do you keep up with new technology?","qzh": "你如何跟上新技术的发展？","points": ["Where you get tech news and ideas","How you actually learn something new","A recent technology you learned","How you deal with information overload"],"phrases": [["keep up with","跟上"],["I learn best by doing","我在实践中学得最好"],["a side project","副业项目、个人小项目"],["get my hands dirty","亲自上手"],["it's impossible to learn everything","不可能什么都学"],["I try to focus on…","我尽量专注于……"]],"sample": "Honestly, it's tough to keep up, because things change so fast. I mostly follow a few YouTube channels and newsletters, and I check Hacker News when I have time. But just reading doesn't really work for me. I learn best by doing, so when I find something interesting, I build a small side project to get my hands dirty. For example, recently I learned how to use AI coding tools in my workflow, and I built a little app with them over a weekend. I think the key thing is accepting that it's impossible to learn everything. So I try to focus on tools that are actually useful for my job, and ignore the hype.","samplezh": "说实话，跟上很难，因为变化太快了。我主要关注几个YouTube频道和技术通讯，有空的时候看看Hacker News。但光读对我来说没什么用。我在实践中学得最好，所以发现有意思的东西，我就做个小项目亲自上手。比如最近我学了怎么在工作流程中用AI编程工具，周末用它们做了一个小应用。我觉得关键是接受一个事实：不可能什么都学。所以我尽量专注于对工作真正有用的工具，忽略那些炒作。"},{"id": "teamwork","cat": "工作","level": "进阶","q": "Do you prefer working alone or in a team? Why?","qzh": "你更喜欢独自工作还是团队合作？为什么？","points": ["Your general preference","Benefits of working in a team","Benefits of working alone","An example from your experience"],"phrases": [["it depends on the task","要看任务"],["bounce ideas off each other","互相碰撞想法"],["get into the zone","进入状态、专注模式"],["on the same page","意见一致、步调一致"],["a second pair of eyes","多一双眼睛帮忙看"],["the best of both worlds","两全其美"]],"sample": "I'd say it really depends on the task. When I'm writing code, I prefer working alone, because I need to get into the zone, and constant interruptions kill my focus. But for planning or solving a really tricky problem, a team is so much better. You can bounce ideas off each other, and someone always sees something you missed. Code review is a good example. Having a second pair of eyes has saved me from so many stupid mistakes. The hard part of teamwork is making sure everyone's on the same page, especially in a remote team. So my ideal setup is a few hours of deep work alone, plus short check-ins with the team. That's the best of both worlds.","samplezh": "我觉得这真的要看任务。写代码的时候，我更喜欢独自工作，因为我需要进入状态，不断被打断会毁掉我的专注。但做规划或者解决特别棘手的问题时，团队要好得多。大家可以互相碰撞想法，总有人能看到你漏掉的东西。代码审查就是个好例子。多一双眼睛帮忙看，让我避免了很多低级错误。团队合作的难点是确保大家步调一致，尤其是远程团队。所以我理想的安排是独自深度工作几个小时，再加上和团队的简短沟通。这样两全其美。"},{"id": "good_manager","cat": "工作","level": "进阶","q": "What makes a good manager?","qzh": "怎样才算一个好经理？","points": ["The most important qualities","How a good manager communicates","An example of a good or bad manager you've had","What you'd do if you were a manager"],"phrases": [["have your back","支持你、罩着你"],["micromanage","事无巨细地管、微观管理"],["give clear feedback","给出清晰的反馈"],["trust the team","信任团队"],["shield the team from…","帮团队挡住……"],["lead by example","以身作则"]],"sample": "For me, a good manager is someone who trusts the team and doesn't micromanage. I had a manager once who wanted updates every two hours, and it was exhausting. I felt like he didn't trust me at all. My current manager is the opposite. She gives clear goals and then lets us figure out how to get there. She also gives honest feedback, but in a kind way, and she always has our back when things go wrong. Another thing I really appreciate is that she shields the team from random requests from other departments. If I were a manager, I'd try to lead by example and make sure people feel safe asking questions.","samplezh": "对我来说，好经理是信任团队、不搞微观管理的人。我以前有个经理每两小时就要一次进度汇报，特别累，我感觉他完全不信任我。我现在的经理正好相反。她给出清晰的目标，然后让我们自己想办法去完成。她也会给出诚实的反馈，但方式很温和，出问题的时候她总是支持我们。我特别欣赏的另一点是，她会帮团队挡住其他部门的各种临时需求。如果我当经理，我会尽量以身作则，让大家觉得提问是安全的。"},{"id": "career_plans","cat": "工作","level": "进阶","q": "Where do you see yourself in five years?","qzh": "你觉得五年后的自己会是什么样？","points": ["Your short-term career goals","Skills you want to develop","Where you'd like to live or work","How you plan to get there"],"phrases": [["in the long run","从长远来看"],["move up to…","晋升到……"],["I'd love to…","我很想……"],["I'm still figuring it out","我还在摸索"],["build my skills in…","提升我在……方面的技能"],["step by step","一步一步地"]],"sample": "That's a big question. Honestly, I'm still figuring it out, but I have a rough idea. In the next couple of years, I want to move up to a senior engineer role, which means building my skills in system design and, you know, communicating better with non-technical people. My English is a big part of that, actually. In the long run, I'd love to work for an international company, maybe fully remote, so I could live anywhere. I've also thought about starting my own small product someday. So my plan is pretty simple. Keep learning, ship side projects, and practice speaking English every day. Step by step, I guess.","samplezh": "这是个大问题。说实话，我还在摸索，但有个大概的想法。接下来几年，我想晋升到高级工程师，这意味着要提升系统设计能力，还有，你知道的，更好地和非技术人员沟通。其实英语是其中很重要的一部分。从长远来看，我很想去国际公司工作，最好是完全远程，这样我可以住在任何地方。我也想过将来做一个自己的小产品。所以我的计划很简单：持续学习，做些个人项目，每天练习说英语。我想就是一步一步来吧。"},{"id": "why_kl","cat": "生活在马来西亚","level": "基础","q": "Why did you decide to move to Kuala Lumpur?","qzh": "你为什么决定搬到吉隆坡？","points": ["The main reason you moved","What you expected before coming","What surprised you","Whether you'd recommend it to others"],"phrases": [["it was a combination of things","是多方面原因"],["a fresh start","重新开始"],["English is widely spoken","英语很普及"],["the cost of living is reasonable","生活成本合理"],["it took some time to adjust","花了一些时间适应"],["I'd definitely recommend it","我绝对会推荐"]],"sample": "It was a combination of things, really. First, I got a job offer here, and the salary was decent compared to the cost of living. Second, I wanted a fresh start somewhere new, but not too far from home. And KL is perfect for that, because lots of people speak Chinese, but English is also widely spoken, so I can practice. Before I came, I thought it would be like a smaller version of Singapore. But it's actually its own thing, more relaxed and more diverse. What surprised me was how friendly people are. It took some time to adjust to the heat and traffic, but overall I'd definitely recommend it.","samplezh": "其实是多方面原因。第一，我在这里拿到了一份工作offer，和生活成本比起来薪水还不错。第二，我想在一个新地方重新开始，但又不离家太远。吉隆坡对此再合适不过了，因为很多人会说中文，但英语也很普及，所以我可以练习。来之前，我以为它会像一个小号的新加坡。但它其实很有自己的特点，更轻松，也更多元。让我惊讶的是这里的人特别友善。适应炎热和交通花了一些时间，但总的来说，我绝对会推荐。"},{"id": "malaysian_food","cat": "生活在马来西亚","level": "基础","q": "What Malaysian food do you like? Is there anything you don't like?","qzh": "你喜欢什么马来西亚食物？有不喜欢的吗？","points": ["Your favorite local dishes","Where you usually eat them","Something you didn't like or found strange","How it compares to food back home"],"phrases": [["my go-to is…","我的首选是……"],["it's super affordable","超级便宜"],["the smell takes some getting used to","那味道需要时间适应"],["it's an acquired taste","是一种需要慢慢接受的口味"],["I'm hooked on…","我迷上了……"],["you can't go wrong with…","……肯定不会错"]],"sample": "Oh, I love Malaysian food. My go-to is nasi lemak, the coconut rice with sambal, fried chicken, peanuts, and an egg. You can get it almost anywhere, and it's super affordable. I'm also hooked on roti canai with curry, especially late at night at a mamak. And you can't go wrong with char kway teow. The one thing I'm still not sure about is durian. A lot of my Malaysian friends love it, but honestly, the smell takes some getting used to. I think it's an acquired taste. Compared to food back home, Malaysian food is spicier and a bit sweeter, and there's way more variety, because you've got Malay, Chinese, and Indian food all in one place.","samplezh": "哦，我超爱马来西亚食物。我的首选是椰浆饭，就是椰香米饭配参巴辣酱、炸鸡、花生和鸡蛋。几乎哪里都能买到，而且超级便宜。我也迷上了印度煎饼配咖喱，尤其是深夜在嘛嘛档吃。炒粿条肯定也不会错。唯一我还拿不准的是榴莲。很多马来西亚朋友都爱吃，但说实话，那个味道需要时间适应。我觉得它是一种需要慢慢接受的口味。和家乡的食物比，马来西亚菜更辣、更甜一点，种类也多得多，因为马来菜、中国菜和印度菜都集中在一个地方。"},{"id": "traffic_transport","cat": "生活在马来西亚","level": "进阶","q": "How do you get around the city? What's the traffic like?","qzh": "你在城里怎么出行？交通状况怎么样？","points": ["Your main way of getting around","What public transport is like","How bad the traffic is","What could be improved"],"phrases": [["I mostly rely on…","我主要依靠……"],["stuck in traffic","堵在路上"],["rush hour","高峰时段"],["it's hit or miss","时好时坏、看运气"],["not very walkable","不太适合步行"],["it adds up","积少成多、钱加起来不少"]],"sample": "I mostly rely on the LRT and Grab. If my destination is near a station, I take the train, because it's cheap and I just tap my Touch 'n Go card. But KL isn't very walkable, so the last part of the trip is often the problem. There's no shade, it's super hot, and sometimes there's no sidewalk at all. That's when I just book a Grab. The traffic, though, can be really bad, especially during rush hour or when it rains. I once spent an hour stuck in traffic for a trip that normally takes fifteen minutes. And Grab prices go up a lot at those times, so it adds up. I think more covered walkways would help a lot.","samplezh": "我主要靠轻轨和Grab。如果目的地在车站附近，我就坐轻轨，因为便宜，刷一下Touch 'n Go卡就行。但吉隆坡不太适合步行，所以最后一段路往往是个问题。没有遮阴，特别热，有时候根本没有人行道。这时候我就直接叫Grab。不过交通可能真的很糟糕，尤其是高峰时段或者下雨的时候。有一次平时十五分钟的路程，我堵了一个小时。而且那个时候Grab价格涨得很厉害，加起来花不少钱。我觉得多建一些有遮盖的步行道会很有帮助。"},{"id": "cost_of_living","cat": "生活在马来西亚","level": "进阶","q": "Is it expensive to live in KL? Talk about the cost of living.","qzh": "住在吉隆坡贵吗？谈谈生活成本。","points": ["Rent and housing","Food and daily expenses","What's cheap and what's expensive","How it compares to other cities"],"phrases": [["it's relatively affordable","相对便宜"],["the rent takes up most of my salary","房租占了我工资的大头"],["bang for your buck","物有所值、性价比高"],["imported stuff is pricey","进口商品很贵"],["it really adds up","累计起来很多"],["I try to stick to a budget","我尽量按预算花钱"]],"sample": "Overall, I'd say it's relatively affordable, especially compared to Singapore or Shanghai. Rent is my biggest expense. I share a condo near an LRT station, and for around RM1,500 a month I get a pool and a gym, which is great bang for your buck. Local food is really cheap. A plate of chicken rice is like ten ringgit. But some things are surprisingly pricey, like imported stuff, cheese, wine, and cars because of the taxes. Eating at cafes in places like Bangsar or KLCC also really adds up. So I try to stick to a budget. I cook at home on weekdays and treat myself on weekends. That way I can still save a bit every month.","samplezh": "总体来说，我觉得相对便宜，尤其是和新加坡或者上海比。房租是我最大的开销。我在一个轻轨站附近和人合租公寓，每月大约一千五百令吉，就有游泳池和健身房，性价比很高。本地食物真的很便宜，一盘鸡饭大概十令吉。但有些东西出奇地贵，比如进口商品、奶酪、红酒，还有因为税的缘故，汽车也很贵。在孟沙或者KLCC这种地方的咖啡馆吃饭，累计起来也很多。所以我尽量按预算花钱。工作日在家做饭，周末犒劳一下自己。这样我每个月还能存一点钱。"},{"id": "festivals","cat": "生活在马来西亚","level": "基础","q": "What festivals are celebrated in Malaysia? Which one do you enjoy most?","qzh": "马来西亚有哪些节日？你最喜欢哪个？","points": ["The main festivals you know","How people celebrate","Your personal experience of one festival","How it compares to festivals back home"],"phrases": [["open house","开放日（节日敞开家门招待客人）"],["the whole city lights up","整座城市灯火通明"],["it's a public holiday","这天是公共假期"],["everyone goes back to their hometown","大家都回老家"],["the city is so empty","城里特别空"],["it's a great way to experience…","这是体验……的好方式"]],"sample": "Malaysia has so many festivals, because there are different cultures here. There's Hari Raya for the Malay community, Chinese New Year, Deepavali for the Indians, and Christmas too. And most of them are public holidays, which is a nice bonus. The one I enjoy most is probably Hari Raya. Last year a coworker invited me to her open house. Her family cooked tons of food, like rendang and ketupat, and they welcomed everyone, even strangers like me. It was such a great way to experience Malay culture. Another fun thing is that during big festivals, everyone goes back to their hometown, so KL is so empty. No traffic at all. Honestly, that's kind of my favorite part.","samplezh": "马来西亚节日特别多，因为这里有不同的文化。有马来人的开斋节、华人新年、印度人的屠妖节，还有圣诞节。而且大部分都是公共假期，算是额外福利。我最喜欢的可能是开斋节。去年一个同事邀请我去她家的开放日。她家做了一大堆吃的，比如仁当和马来粽，他们欢迎所有人，连我这样的陌生人也欢迎。这是体验马来文化的好方式。还有一件有趣的事，大节日期间大家都回老家，所以吉隆坡特别空，一点都不堵车。说实话，这算是我最喜欢的部分。"},{"id": "language_mix","cat": "生活在马来西亚","level": "进阶","q": "Malaysians often mix languages. What do you think about that?","qzh": "马来西亚人经常混着说几种语言，你怎么看？","points": ["Which languages you hear every day","Examples of mixing, like Manglish","How it affects your own English","Whether you think it's good or bad"],"phrases": [["switch between languages","在几种语言之间切换"],["in the same sentence","在同一句话里"],["it confused me at first","一开始让我很困惑"],["pick up a few words","学会几个词"],["it's part of the culture","这是文化的一部分"],["I've started saying 'lah' myself","我自己也开始说lah了"]],"sample": "Yeah, that's one of the most interesting things about living here. In one day I can hear English, Malay, Mandarin, Cantonese, and Tamil. And people switch between languages in the same sentence. Like, someone will say, 'Eh, can or not? Later we go makan lah.' It confused me at first, because the English sounds a bit different from what I learned in school. But now I think it's actually really cool. It's part of the culture, and it shows how diverse the country is. I've picked up a few Malay words too, like makan and jalan, and honestly, I've started saying 'lah' myself. The only downside is I need to be careful to use standard English at work.","samplezh": "对，这是住在这里最有意思的事情之一。一天之内我能听到英语、马来语、普通话、粤语和泰米尔语。而且大家会在同一句话里切换语言。比如有人会说：“诶，可以吗？等下我们去吃饭啦。”一开始这让我很困惑，因为这种英语听起来和我在学校学的有点不一样。但现在我觉得这其实很酷。这是文化的一部分，也体现了这个国家有多元。我也学会了几个马来语词，比如makan（吃）和jalan（走），说实话，我自己也开始说“lah”了。唯一的缺点是工作时我得注意用标准英语。"},{"id": "best_trip","cat": "旅行","level": "基础","q": "Describe the best trip you've ever taken.","qzh": "描述一下你最棒的一次旅行。","points": ["Where you went and who you went with","What you did there","The highlight of the trip","Why it was so special"],"phrases": [["hands down","毫无疑问"],["the highlight was…","最精彩的是……"],["breathtaking views","令人惊叹的风景"],["we got lost","我们迷路了"],["it was totally worth it","完全值得"],["I'd go back in a heartbeat","我会毫不犹豫再去"]],"sample": "Hands down, my best trip was to Japan two years ago. I went with two close friends for about ten days. We started in Tokyo, then took the bullet train to Kyoto and Osaka. We did all the touristy stuff, temples, shrines, and so much street food. But the highlight was a day trip to a small town near Mount Fuji. The weather was perfect, and the views were breathtaking. We actually got lost on the way back and missed the last bus, so we had to walk for an hour. It was exhausting but kind of hilarious. I think it was special because everything was so clean and organized. I'd go back in a heartbeat.","samplezh": "毫无疑问，我最棒的一次旅行是两年前去日本。我和两个好朋友一起去了大概十天。我们从东京出发，然后坐新干线去了京都和大阪。所有游客会做的事我们都做了，寺庙、神社，还吃了超多街头小吃。但最精彩的是去富士山附近一个小镇的一日游。天气特别好，风景令人惊叹。回来的路上我们还迷路了，错过了末班车，只好走了一个小时。很累，但也挺搞笑的。我觉得它特别，是因为一切都那么干净有序。我会毫不犹豫再去。"},{"id": "dream_destination","cat": "旅行","level": "基础","q": "If you could travel anywhere, where would you go?","qzh": "如果可以去任何地方旅行，你会去哪里？","points": ["The place and why you chose it","What you'd like to see or do","Who you'd go with","What's stopping you right now"],"phrases": [["it's been on my bucket list for years","它在我的人生愿望清单上好多年了"],["I've always wanted to…","我一直想……"],["see it with my own eyes","亲眼看看"],["road trip","自驾游"],["it's a bit out of my budget","有点超出我的预算"],["one day for sure","总有一天一定会去"]],"sample": "If I could go anywhere, I'd pick Iceland. It's been on my bucket list for years. I've always wanted to see the northern lights with my own eyes, and Iceland looks like another planet, with glaciers, volcanoes, black sand beaches, all that stuff. I'd love to rent a car and do a road trip around the whole island, maybe for two weeks. Ideally I'd go with a couple of friends who like hiking and photography. Honestly, the main thing stopping me is money. Iceland is super expensive, so it's a bit out of my budget right now. Also, coming from Malaysia, I'm not sure I could handle the cold. But one day, for sure.","samplezh": "如果可以去任何地方，我会选冰岛。它在我的人生愿望清单上好多年了。我一直想亲眼看看北极光，冰岛看起来像另一个星球，有冰川、火山、黑沙滩之类的。我很想租辆车环岛自驾，大概两周。最好和几个喜欢徒步和摄影的朋友一起去。说实话，阻止我的主要是钱。冰岛特别贵，现在有点超出我的预算。而且我在马来西亚待惯了，不确定能不能扛得住那种冷。但总有一天，我一定会去。"},{"id": "travel_tips","cat": "旅行","level": "进阶","q": "What tips would you give someone planning a trip abroad?","qzh": "你会给计划出国旅行的人什么建议？","points": ["Planning and booking","Packing and money","Staying safe and healthy","Making the most of the trip"],"phrases": [["book in advance","提前预订"],["pack light","轻装出行"],["don't overplan","别把行程排太满"],["get a local SIM card","买一张当地电话卡"],["keep a copy of your passport","留一份护照复印件"],["off the beaten path","人少的、非热门的地方"]],"sample": "Okay, my first tip is to book flights and hotels in advance, but don't overplan. I used to pack every hour with activities, and I just ended up exhausted. Leave some free time to wander around. Second, pack light. You really don't need five pairs of shoes, trust me. Third, get a local SIM card or an eSIM as soon as you land, because having maps and Grab or Uber makes everything easier. For safety, keep a copy of your passport on your phone and in your email, just in case. And finally, try to go somewhere off the beaten path for at least one day. Some of my best memories are from places that weren't in any guidebook.","samplezh": "好，我的第一个建议是提前预订机票和酒店，但别把行程排太满。我以前每个小时都塞满活动，结果累得要命。留点空闲时间随便逛逛。第二，轻装出行。相信我，你真的不需要带五双鞋。第三，一落地就买当地电话卡或者eSIM，因为有了地图和Grab或Uber，一切都容易多了。安全方面，在手机和邮箱里各存一份护照复印件，以防万一。最后，至少花一天去个人少的、非热门的地方。我很多最美好的回忆都来自那些旅游指南上没有的地方。"},{"id": "travel_problem","cat": "旅行","level": "进阶","q": "Have you ever had a problem while traveling? What happened?","qzh": "你旅行时遇到过麻烦吗？发生了什么？","points": ["Where you were and what went wrong","How you felt at the time","What you did to fix it","What you learned from it"],"phrases": [["my flight got cancelled","我的航班被取消了"],["I was freaking out","我当时特别慌"],["luckily","幸运的是"],["I had no choice but to…","我别无选择，只能……"],["it turned into a good story","后来成了一个好故事"],["now I always…","现在我总是……"]],"sample": "Yeah, actually. A couple of years ago I was flying back from Bangkok, and my flight got cancelled at the last minute because of a storm. It was late at night, the airport was packed, and everyone was trying to rebook at the same time. Honestly, I was freaking out a little, because I had work the next morning. The line was super long, so I had no choice but to call the airline while waiting. Luckily, I got through and they put me on a flight the next afternoon, plus a free hotel. I just had to message my manager and work remotely. Now it's turned into a funny story, and I always buy travel insurance.","samplezh": "有的。几年前我从曼谷飞回来，航班因为暴风雨在最后一刻被取消了。那时候是深夜，机场挤满了人，大家都在同时改签。说实话，我当时有点慌，因为第二天早上还要上班。队排得特别长，我别无选择，只能一边排队一边给航空公司打电话。幸运的是，电话打通了，他们帮我改到第二天下午的航班，还提供了免费酒店。我只需要给经理发消息，远程办公就行。现在这成了一个有趣的故事，而且我现在总是买旅行保险。"},{"id": "solo_vs_group","cat": "旅行","level": "进阶","q": "Do you prefer traveling alone or with other people?","qzh": "你更喜欢一个人旅行还是和别人一起？","points": ["Your preference and why","Advantages of solo travel","Advantages of group travel","A personal experience of either"],"phrases": [["do whatever I want","想做什么就做什么"],["step out of my comfort zone","走出舒适区"],["split the cost","分摊费用"],["it can get lonely","可能会孤单"],["we didn't always agree on…","我们在……上不总是意见一致"],["a mix of both","两者结合"]],"sample": "I've done both, and they're really different. When I travel alone, I can do whatever I want. If I want to spend three hours in a museum or skip breakfast, nobody cares. It also forces me to step out of my comfort zone and talk to locals, which is great for my English. But it can get lonely, especially at dinner. Traveling with friends is more fun, and you can split the cost of hotels and taxis. On my last group trip, though, we didn't always agree on where to go, and it got a bit tense. So I think my ideal is a mix of both. Travel with friends, but spend a day or two exploring on my own.","samplezh": "两种我都试过，真的很不一样。一个人旅行时，我想做什么就做什么。想在博物馆待三个小时或者不吃早餐，都没人管。这也逼着我走出舒适区，和当地人交流，对我的英语特别有帮助。但可能会孤单，尤其是吃晚饭的时候。和朋友一起旅行更好玩，还能分摊酒店和打车的费用。不过上次团体旅行时，我们在去哪儿这件事上不总是意见一致，气氛有点紧张。所以我觉得理想的是两者结合：和朋友一起去，但留一两天自己去探索。"},{"id": "beach_vs_city","cat": "旅行","level": "基础","q": "Which do you prefer for a holiday, the beach or the city?","qzh": "度假的话，你更喜欢海边还是城市？","points": ["Your choice and the main reason","What you like doing at the beach","What you like doing in a city","A place that combines both"],"phrases": [["I'm more of a … person","我更偏向……的人"],["unwind","放松下来"],["lie on the beach doing nothing","躺在沙滩上什么都不做"],["there's so much to explore","有太多可以探索的"],["get bored easily","很容易无聊"],["it has the best of both","两者的优点都有"]],"sample": "Hmm, I think I'm more of a beach person, at least lately. My job involves staring at a screen all day, so on holiday I just want to unwind, lie on the beach doing nothing, and maybe go snorkeling. Places like Langkawi or the islands off Terengganu are perfect for that. But to be fair, I get bored easily, so after three days of beach I start missing the city. Cities have so much to explore, like food markets, museums, and cool neighborhoods. So honestly, my favorite places are ones that have the best of both, like Penang. You can eat amazing street food in George Town, and then go to the beach in the afternoon.","samplezh": "嗯，我觉得我更偏向海边，至少最近是这样。我的工作整天盯着屏幕，所以度假时我只想放松，躺在沙滩上什么都不做，也许去浮潜。像兰卡威或者登嘉楼外面的那些岛就很完美。不过说句公道话，我很容易无聊，在海边待三天后就开始想念城市了。城市有太多可以探索的，比如美食市集、博物馆，还有很酷的街区。所以说实话，我最喜欢的地方是两者优点都有的，比如槟城。你可以在乔治市吃超棒的街头小吃，下午再去海边。"},{"id": "fitness","cat": "兴趣","level": "基础","q": "How do you stay fit and healthy?","qzh": "你怎么保持身体健康？","points": ["The kind of exercise you do","How often you work out","Your eating habits","How you stay motivated"],"phrases": [["work out","锻炼、健身"],["hit the gym","去健身房"],["I'm trying to cut down on…","我在努力少吃……"],["stay consistent","坚持下去"],["it's a great stress reliever","这是很好的减压方式"],["I fell off the wagon","我中断了（坚持的习惯）"]],"sample": "I try to work out three or four times a week. There's a small gym in my condo, so I usually hit the gym after work, mostly weights, plus some running on the treadmill. On weekends I sometimes go hiking, like at Bukit Kiara. For food, I'm trying to cut down on sugar and late-night snacks, which is hard in Malaysia because there's so much good food everywhere. Honestly, the hardest part is staying consistent. Last year I fell off the wagon for like two months when work got busy. What keeps me motivated now is tracking my progress with an app, and also knowing that exercise is a great stress reliever. I always feel better afterward.","samplezh": "我尽量每周锻炼三四次。我住的公寓里有个小健身房，所以我一般下班后去健身，主要练器械，再在跑步机上跑一会儿。周末有时候去徒步，比如去武吉吉拉。饮食方面，我在努力少吃糖和宵夜，这在马来西亚挺难的，因为到处都是好吃的。说实话，最难的是坚持。去年工作一忙，我中断了大概两个月。现在让我保持动力的，是用App记录进度，还有知道运动是很好的减压方式。锻炼完我总是感觉更好。"},{"id": "movie_show","cat": "兴趣","level": "基础","q": "Tell me about a movie or TV show you really enjoyed.","qzh": "说说一部你很喜欢的电影或电视剧。","points": ["What it's called and what it's about","The characters or actors","Why you liked it","Whether you'd recommend it"],"phrases": [["I binge-watched it","我一口气追完了"],["it's about…","它讲的是……"],["no spoilers, but…","不剧透，但是……"],["the plot twist","剧情反转"],["it's really well written","编剧写得很好"],["it kept me hooked","它让我欲罢不能"]],"sample": "One show I really enjoyed recently is Severance. It's about people who work at a company where their work memories are completely separated from their personal lives. So the work version of you doesn't know anything about your real life. It sounds weird, but it's super interesting, especially for someone who works in an office. No spoilers, but the plot twists in season one are amazing. It kept me hooked, and I binge-watched the whole thing in one weekend. I think I liked it because it's really well written, and it makes you think about work-life balance in a creepy way. Also, it's great for English practice, because the dialogue is clear. I'd definitely recommend it.","samplezh": "我最近很喜欢的一部剧是《人生切割术》。它讲的是一群人在一家公司工作，他们的工作记忆和私人生活被完全分开。所以工作中的你对自己真实的生活一无所知。听起来很怪，但特别有意思，尤其是对上班族来说。不剧透，但第一季的剧情反转太精彩了。它让我欲罢不能，我一个周末就一口气追完了。我觉得我喜欢它是因为编剧写得很好，而且它以一种有点诡异的方式让你思考工作与生活的平衡。另外它很适合练英语，因为对白很清楚。我绝对推荐。"},{"id": "music","cat": "兴趣","level": "基础","q": "What kind of music do you listen to?","qzh": "你听什么类型的音乐？","points": ["Your favorite genres or artists","When and where you listen to music","How your taste has changed","Music for different moods"],"phrases": [["I'm really into…","我特别喜欢……"],["it depends on my mood","要看我的心情"],["background music","背景音乐"],["it helps me focus","它帮我集中注意力"],["I have it on repeat","我在单曲循环"],["my taste has changed","我的口味变了"]],"sample": "It really depends on my mood. When I'm coding, I like lo-fi or instrumental stuff, because songs with lyrics distract me. It's just nice background music, and it helps me focus. When I'm at the gym, I need something with energy, like hip-hop or EDM. And on a lazy Sunday, I'm really into indie pop and some old Chinese songs from the 2000s. My taste has changed a lot, actually. When I was a teenager, I only listened to Chinese pop, but since I started learning English, I listen to way more English songs. Right now I have a Taylor Swift album on repeat, mostly because the lyrics are easy to follow.","samplezh": "这真的要看我的心情。写代码的时候，我喜欢lo-fi或者纯音乐，因为有歌词的歌会让我分心。它就是很好的背景音乐，能帮我集中注意力。在健身房，我需要有能量的音乐，比如嘻哈或电子舞曲。而在慵懒的周日，我特别喜欢独立流行和一些2000年代的华语老歌。其实我的口味变了很多。十几岁时我只听华语流行，但开始学英语以后，我听的英文歌多了很多。现在我在循环播放一张泰勒·斯威夫特的专辑，主要是因为歌词很容易听懂。"},{"id": "book_youtube","cat": "兴趣","level": "进阶","q": "Tell me about a book or YouTube channel that influenced you.","qzh": "说说一本对你有影响的书或一个YouTube频道。","points": ["What it is and how you found it","What it's about","What you learned from it","How it changed your habits or thinking"],"phrases": [["I came across it by accident","我偶然发现的"],["it really opened my eyes","它让我大开眼界"],["break it down","把它拆解讲清楚"],["the main idea is…","核心观点是……"],["it stuck with me","它让我一直记着"],["I put it into practice","我付诸实践"]],"sample": "One book that really influenced me is Atomic Habits by James Clear. I came across it by accident, actually. A coworker had it on his desk, and I borrowed it. The main idea is that small habits, like getting one percent better every day, add up to huge results over time. He also breaks down how to build good habits, like making them obvious and easy. That really stuck with me. Before, I'd set huge goals, like studying English two hours a day, and quit after a week. So I put it into practice. Now I just do fifteen minutes of English every morning with my coffee, and I've kept it up for months.","samplezh": "一本对我影响很大的书是詹姆斯·克利尔的《掌控习惯》。其实是偶然发现的。一个同事桌上放着这本书，我就借来看了。核心观点是，小习惯，比如每天进步百分之一，时间长了会积累成巨大的成果。他还把如何养成好习惯拆解得很清楚，比如让习惯显而易见、简单易行。这让我一直记着。以前我会定很大的目标，比如每天学两个小时英语，结果一周就放弃了。所以我付诸实践。现在我每天早上边喝咖啡边学十五分钟英语，已经坚持好几个月了。"},{"id": "cooking","cat": "兴趣","level": "基础","q": "Do you like cooking? What can you cook?","qzh": "你喜欢做饭吗？你会做什么？","points": ["How often you cook","Dishes you're good at","How you learned","Cooking vs eating out"],"phrases": [["I'm not a great cook, but…","我厨艺不算好，但……"],["my signature dish","我的拿手菜"],["follow a recipe","照着食谱做"],["meal prep","提前备餐"],["it's healthier and cheaper","更健康也更省钱"],["I learned from my mom","我跟我妈学的"]],"sample": "I'm not a great cook, but I do enjoy it. I cook maybe three or four times a week, mostly simple Chinese home-style dishes. My signature dish is tomato and egg stir-fry. It sounds basic, but everyone loves it. I learned it from my mom when I was in university, and she still gives me tips over video calls. Recently I've started following YouTube recipes to try new things, like Thai green curry. On Sundays I sometimes meal prep for the week, so I don't have to think about lunch. Honestly, eating out in Malaysia is so cheap that cooking isn't always necessary, but cooking at home is healthier, and it's kind of relaxing after work.","samplezh": "我厨艺不算好，但我挺享受的。我一周大概做三四次饭，主要是简单的中式家常菜。我的拿手菜是西红柿炒鸡蛋。听起来很普通，但大家都爱吃。我上大学时跟我妈学的，她现在还会通过视频电话给我指点。最近我开始照着YouTube上的食谱尝试新菜，比如泰式绿咖喱。周日我有时会提前备好一周的饭，这样就不用为午饭发愁。说实话，在马来西亚外面吃饭太便宜了，做饭不一定必要，但在家做饭更健康，而且下班后做饭挺放松的。"},{"id": "learning_english","cat": "兴趣","level": "进阶","q": "How are you learning English, and what's the hardest part?","qzh": "你是怎么学英语的？最难的部分是什么？","points": ["Why you're learning English","Methods and resources you use","The hardest part for you","How you measure your progress"],"phrases": [["my main goal is to…","我的主要目标是……"],["I'm pretty good at… but…","我……还挺好，但……"],["it's hard to keep up with native speakers","跟上母语者很难"],["I freeze up","我会卡住、大脑一片空白"],["shadowing","跟读"],["I can tell I'm improving","我能感觉到自己在进步"]],"sample": "My main goal is to speak more naturally, especially at work and in daily life here. I'm pretty good at reading, because I read technical docs all the time, but speaking is a different story. The hardest part is listening to native speakers. When I watch American YouTubers, they talk so fast and use so much slang, it's hard to keep up. And when I have to speak in a meeting, sometimes I just freeze up. So now I'm doing shadowing every day. I pick a short clip, listen, and repeat it sentence by sentence. I also try to describe my day out loud. It's slow, but I can tell I'm improving. I hesitate less than before.","samplezh": "我的主要目标是说得更自然，尤其是工作和在这里的日常生活中。我阅读还挺好的，因为一直在看技术文档，但口语就是另一回事了。最难的是听懂母语者说话。看美国YouTuber的视频时，他们说得太快，俚语又多，很难跟上。在会议上要发言时，有时候我会直接卡住。所以现在我每天做跟读练习。我挑一段短视频，听一遍，然后一句一句地重复。我也会试着大声描述自己的一天。进步很慢，但我能感觉到自己在进步，说话时犹豫得比以前少了。"},{"id": "ai_and_jobs","cat": "观点","level": "进阶","q": "Do you think AI will take away people's jobs?","qzh": "你认为AI会抢走人们的工作吗？","points": ["Your overall opinion","Jobs that are most at risk","How AI is changing your own work","How people can prepare"],"phrases": [["it's a tricky question","这个问题很难说"],["on the one hand… on the other hand…","一方面……另一方面……"],["replace vs. assist","取代与辅助"],["repetitive tasks","重复性工作"],["stay ahead of the curve","保持领先"],["I'd rather… than…","我宁愿……也不……"]],"sample": "That's a tricky question. On the one hand, I think AI will definitely replace some jobs, especially ones with a lot of repetitive tasks, like basic data entry or simple customer service. On the other hand, it's creating new kinds of work too. In my own job, AI tools already write a lot of boilerplate code for me. So I spend less time typing and more time thinking about design and reviewing what the AI writes. I don't think it'll replace good engineers soon, but engineers who use AI might replace engineers who don't. So I think the best way to prepare is to stay ahead of the curve. I'd rather learn to use it than be afraid of it.","samplezh": "这个问题很难说。一方面，我认为AI肯定会取代一些工作，尤其是有很多重复性任务的工作，比如基础的数据录入或简单的客服。另一方面，它也在创造新的工作。在我自己的工作中，AI工具已经帮我写了很多样板代码。所以我花在敲代码上的时间少了，更多时间在思考设计、审查AI写的东西。我觉得它短期内不会取代优秀的工程师，但会用AI的工程师可能会取代不会用的工程师。所以我认为最好的准备方式是保持领先。我宁愿学会用它，也不愿害怕它。"},{"id": "social_media","cat": "观点","level": "进阶","q": "Is social media doing more harm than good?","qzh": "社交媒体弊大于利吗？","points": ["The benefits of social media","The negative effects","Who is most affected","How to use it in a healthy way"],"phrases": [["stay connected","保持联系"],["compare yourself to others","和别人比较"],["it's designed to be addictive","它就是被设计成让人上瘾的"],["fake news spreads fast","假新闻传播很快"],["it's not black and white","这不是非黑即白的"],["in moderation","适度地"]],"sample": "I think it's not black and white. There are real benefits. I live far from my family, and social media helps me stay connected with them every day. I also learn a ton from it, like English and coding tips. But there are serious downsides too. A lot of apps are designed to be addictive, and people waste hours scrolling. And when you see everyone's perfect life online, it's easy to compare yourself to others and feel bad. Fake news also spreads really fast. I think teenagers are the most affected, because they're still figuring out who they are. So for me, the key is using it in moderation and following accounts that actually make your life better.","samplezh": "我觉得这不是非黑即白的。它确实有好处。我住得离家人很远，社交媒体帮我每天和他们保持联系。我也从上面学到了很多，比如英语和编程技巧。但它也有严重的坏处。很多App就是被设计成让人上瘾的，人们刷几个小时就浪费掉了。而且看到网上大家完美的生活，很容易和别人比较，然后感觉很糟。假新闻也传播得特别快。我认为青少年受影响最大，因为他们还在探索自己是谁。所以对我来说，关键是适度使用，关注那些真正让你生活更好的账号。"},{"id": "remote_vs_office","cat": "观点","level": "进阶","q": "Is remote work better than working in an office?","qzh": "远程办公比在办公室上班更好吗？","points": ["Advantages of remote work","Advantages of the office","Which types of people or jobs suit each","Your conclusion"],"phrases": [["flexibility","灵活性"],["face-to-face","面对面"],["it's harder to build relationships","更难建立关系"],["it boils down to…","归根结底在于……"],["it suits some people more than others","它更适合某些人"],["hybrid is the sweet spot","混合办公是最佳平衡点"]],"sample": "Honestly, I think it boils down to the person and the job. Remote work gives you a lot of flexibility. You save time on commuting, and you can focus without office noise. For developers like me, that's a big plus. But the office has real advantages too. Face-to-face conversations are just faster, and it's way easier to build relationships with coworkers. When I started my job fully remote, it took months to feel like part of the team. I also think junior people learn faster in an office, because they can just turn around and ask someone. So remote work suits some people more than others. For most teams, I'd say hybrid is the sweet spot.","samplezh": "说实话，我觉得归根结底在于人和工作本身。远程办公给你很大的灵活性。你省下了通勤时间，没有办公室的噪音也能更专注。对我这样的开发者来说，这是很大的优点。但办公室也有真正的优势。面对面交流就是更快，和同事建立关系也容易得多。我刚开始工作时是完全远程的，花了好几个月才感觉自己是团队的一员。我也认为新人在办公室学得更快，因为他们一转身就能问人。所以远程办公更适合某些人。对大多数团队来说，我觉得混合办公是最佳平衡点。"},{"id": "city_vs_countryside","cat": "观点","level": "基础","q": "Is it better to live in a big city or in the countryside?","qzh": "住在大城市好还是住在乡村好？","points": ["Advantages of city life","Advantages of the countryside","What matters most at different life stages","Where you'd like to live in the future"],"phrases": [["there are more opportunities","机会更多"],["peace and quiet","安静平和"],["the rat race","激烈的竞争、忙碌的生活"],["at this stage of my life","在我人生的这个阶段"],["settle down","安定下来"],["get away from it all","远离一切喧嚣"]],"sample": "I think it depends on what stage of life you're at. Right now, I definitely prefer the city. There are more opportunities, especially for jobs in tech, and everything is convenient. I can get food delivered at midnight, and there's always something to do. But city life can be stressful. It's noisy, crowded, and sometimes it feels like a rat race. The countryside has peace and quiet, fresh air, and a slower lifestyle. When I go to places like Cameron Highlands, I feel so relaxed. So maybe when I'm older and want to settle down, I'd love to live somewhere quieter. Or, ideally, a small town not too far from a big city, so I can get away from it all.","samplezh": "我觉得这要看你处在人生的哪个阶段。现在我肯定更喜欢城市。机会更多，尤其是科技类的工作，而且一切都很方便。半夜也能点外卖，总有事情可做。但城市生活可能压力很大。吵闹、拥挤，有时感觉像一场激烈的竞争。乡村有安静平和的环境、新鲜的空气和更慢的生活节奏。我去金马伦高原这种地方时，感觉特别放松。所以也许等我年纪大了、想安定下来的时候，我很想住在安静一点的地方。或者最理想的是，住在离大城市不远的小镇，这样就能远离喧嚣。"},{"id": "kids_and_screens","cat": "观点","level": "进阶","q": "Should children be allowed to use phones and tablets?","qzh": "应该让孩子用手机和平板吗？","points": ["Possible benefits for kids","Risks and concerns","What age might be appropriate","What parents can do"],"phrases": [["it's all about balance","关键在于平衡"],["keep kids busy","让孩子有事做、不吵闹"],["attention span","注意力持续时间"],["set boundaries","设定界限"],["educational apps","教育类应用"],["lead by example","以身作则"]],"sample": "I don't have kids myself, but I see this a lot, like at restaurants where every child has an iPad. I think it's all about balance. There are some benefits. There are great educational apps, and kids need to learn how to use technology anyway. But I'm worried about too much screen time. It can hurt kids' attention span and sleep, and they spend less time playing outside or talking to people. Honestly, I think a lot of parents use tablets just to keep kids busy, which I understand, but it can become a habit. So I'd say young kids should use them only a little, and parents need to set boundaries. And they should lead by example, too.","samplezh": "我自己没有孩子，但这种情况见得很多，比如在餐厅里每个小孩都拿着iPad。我觉得关键在于平衡。它有一些好处。有很好的教育类应用，而且孩子反正也要学会使用科技。但我担心屏幕时间太长。它可能损害孩子的注意力和睡眠，他们出去玩或者和人交流的时间也少了。说实话，我觉得很多家长用平板只是为了让孩子安静，我能理解，但这可能会变成习惯。所以我认为小孩子应该少用，家长需要设定界限。而且家长自己也应该以身作则。"},{"id": "money_vs_happiness","cat": "观点","level": "进阶","q": "Can money buy happiness?","qzh": "金钱能买到幸福吗？","points": ["How money helps with happiness","The limits of money","Other things that make people happy","Your personal view"],"phrases": [["up to a point","在一定程度上"],["peace of mind","内心的安宁"],["financial security","财务安全"],["it's not everything","它不是一切"],["at the end of the day","说到底、归根结底"],["what really matters is…","真正重要的是……"]],"sample": "I think money can buy happiness, but only up to a point. If you don't have enough money to pay rent or go to the doctor, life is really stressful. So having financial security gives you peace of mind, and that's a big part of being happy. Money also gives you freedom, like quitting a job you hate or traveling. But once your basic needs are covered, I don't think more money makes a huge difference. I know people who earn a lot but work crazy hours and look miserable. At the end of the day, what really matters is your health, your relationships, and doing something you find meaningful. Money helps, but it's not everything.","samplezh": "我觉得金钱能买到幸福，但只是在一定程度上。如果你没有足够的钱交房租或者看医生，生活真的会很有压力。所以有财务安全能让你内心安宁，这是幸福很重要的一部分。钱也能给你自由，比如辞掉讨厌的工作，或者去旅行。但一旦基本需求满足了，我不觉得更多的钱会带来很大的区别。我认识一些人赚很多钱，但工作时间长得离谱，看起来很痛苦。说到底，真正重要的是你的健康、你的人际关系，还有做你觉得有意义的事。钱有帮助，但它不是一切。"}]};
